window.KOTOBA_LISTENING_REVIEWS={"lesson:22:meaning":{"title":"Hiragana: the rest of the chart","front":"Where are the beautiful flowers?","answer":"On the mountain.","context":"","promptAudio":"よる、やまの はなが きれいです。","model":"よる、やまの はなが きれいです。","audioText":"よる、やまの はなが きれいです。","note":"“やまの はな” — やまの links the flowers to the mountain.","source":"course.html#lesson-22"},"lesson:27:meaning":{"title":"Voiced sounds and small や","front":"How does the speaker travel to the hospital?","answer":"By bicycle.","context":"","promptAudio":"じてんしゃで びょういんへ いきます。","model":"じてんしゃで びょういんへ いきます。","audioText":"じてんしゃで びょういんへ いきます。","note":"“じてんしゃで” — で marks the bicycle as the means of travel.","source":"course.html#lesson-27"},"lesson:32:meaning":{"title":"Katakana and loanwords","front":"When is the friend coming?","answer":"Tomorrow.","context":"","promptAudio":"あした、アメリカから ともだちが きます。","model":"あした、アメリカから ともだちが きます。","audioText":"あした、アメリカから ともだちが きます。","note":"“あした” — あした identifies tomorrow.","source":"course.html#lesson-32"},"lesson:37:meaning":{"title":"Greetings for the time of day","front":"Which greeting belongs to the evening?","answer":"こんばんは.","context":"","promptAudio":"あさは おはよう、よるは こんばんは。","model":"あさは おはよう、よるは こんばんは。","audioText":"あさは おはよう、よるは こんばんは。","note":"“よるは こんばんは” — The recording pairs night with こんばんは.","source":"course.html#lesson-37"},"lesson:42:meaning":{"title":"Introduce yourself","front":"What does the speaker say about themselves?","answer":"They are a student who enjoys music.","context":"","promptAudio":"わたしは がくせいです。しゅみは おんがくです。","model":"わたしは がくせいです。しゅみは おんがくです。","audioText":"わたしは がくせいです。しゅみは おんがくです。","note":"“がくせいです。しゅみは おんがく” — Both their role and hobby are stated.","source":"course.html#lesson-42"},"lesson:47:meaning":{"title":"Numbers, prices and いくら","front":"Which item costs one thousand yen?","answer":"The sushi.","context":"","promptAudio":"りんごは ひゃくえん、すしは せんえんです。","model":"りんごは ひゃくえん、すしは せんえんです。","audioText":"りんごは ひゃくえん、すしは せんえんです。","note":"“すしは せんえん” — Sushi is one thousand yen; the apple is one hundred.","source":"course.html#lesson-47"},"lesson:52:meaning":{"title":"A is B: です and じゃない","front":"Which person is a student?","answer":"Ana.","context":"","promptAudio":"わたしは アナです。がくせいです。たなかさんは せんせいです。わたしは せんせいじゃありません。","model":"わたしは アナです。がくせいです。たなかさんは せんせいです。わたしは せんせいじゃありません。","audioText":"わたしは アナです。がくせいです。たなかさんは せんせいです。わたしは せんせいじゃありません。","note":"“わたしは アナです。がくせいです” — The speaker identifies herself as Ana and then says she is a student.","source":"course.html#lesson-52"},"lesson:57:meaning":{"title":"This, that, and which","front":"Which bag belongs to Tanaka?","answer":"The bag called それ.","context":"","promptAudio":"これは わたしの かばんです。それは たなかさんの かばんです。あれは だれの かばんですか。","model":"これは わたしの かばんです。それは たなかさんの かばんです。あれは だれの かばんですか。","audioText":"これは わたしの かばんです。それは たなかさんの かばんです。あれは だれの かばんですか。","note":"“それは たなかさんの” — それ is explicitly connected to Tanaka's bag.","source":"course.html#lesson-57"},"lesson:62:meaning":{"title":"There is: あります and います","front":"Where is the book?","answer":"On the desk.","context":"","promptAudio":"へやに つくえが あります。つくえの うえに ほんが あります。ねこは いすの したに います。","model":"へやに つくえが あります。つくえの うえに ほんが あります。ねこは いすの したに います。","audioText":"へやに つくえが あります。つくえの うえに ほんが あります。ねこは いすの したに います。","note":"“つくえの うえに ほん” — The book is above the desk; the cat is under the chair.","source":"course.html#lesson-62"},"lesson:67:meaning":{"title":"い-adjectives","front":"What is the first room like?","answer":"Spacious but a little dark.","context":"","promptAudio":"この へやは ひろいです。でも、すこし くらいです。となりの へやは せまいですが、あかるいです。","model":"この へやは ひろいです。でも、すこし くらいです。となりの へやは せまいですが、あかるいです。","audioText":"この へやは ひろいです。でも、すこし くらいです。となりの へやは せまいですが、あかるいです。","note":"“ひろいです。でも、すこし くらい” — The first room is spacious; the contrasting next-door room is bright.","source":"course.html#lesson-67"},"lesson:72:meaning":{"title":"な-adjectives and すき","front":"What kind of town does the friend like?","answer":"A lively town.","context":"","promptAudio":"この まちは しずかです。わたしは しずかな まちが すきです。ともだちは にぎやかな まちが すきです。","model":"この まちは しずかです。わたしは しずかな まちが すきです。ともだちは にぎやかな まちが すきです。","audioText":"この まちは しずかです。わたしは しずかな まちが すきです。ともだちは にぎやかな まちが すきです。","note":"“ともだちは にぎやかな” — The friend's preference is lively; quiet is the speaker's preference.","source":"course.html#lesson-72"},"lesson:77:meaning":{"title":"Polite verbs: ます and ません","front":"What does the friend drink in the evening?","answer":"Tea.","context":"","promptAudio":"わたしは あさ、コーヒーを のみます。よるは のみません。ともだちは あさも よるも おちゃを のみます。","model":"わたしは あさ、コーヒーを のみます。よるは のみません。ともだちは あさも よるも おちゃを のみます。","audioText":"わたしは あさ、コーヒーを のみます。よるは のみません。ともだちは あさも よるも おちゃを のみます。","note":"“あさも よるも おちゃ” — も indicates that tea is drunk both morning and evening.","source":"course.html#lesson-77"},"lesson:82:meaning":{"title":"The を particle","front":"What does the speaker NOT do today?","answer":"Watch television.","context":"","promptAudio":"わたしは パンを たべます。みずを のみます。それから、ほんを よみます。きょうは テレビを みません。","model":"わたしは パンを たべます。みずを のみます。それから、ほんを よみます。きょうは テレビを みません。","audioText":"わたしは パンを たべます。みずを のみます。それから、ほんを よみます。きょうは テレビを みません。","note":"“テレビを みません” — みません explicitly negates watching television.","source":"course.html#lesson-82"},"lesson:87:meaning":{"title":"Going to, being at, meeting at","front":"What happens after meeting at the station?","answer":"They eat lunch at a cafe.","context":"","promptAudio":"あした、きょうとへ いきます。えきで ともだちに あいます。それから、カフェで ひるごはんを たべます。","model":"あした、きょうとへ いきます。えきで ともだちに あいます。それから、カフェで ひるごはんを たべます。","audioText":"あした、きょうとへ いきます。えきで ともだちに あいます。それから、カフェで ひるごはんを たべます。","note":"“それから、カフェで ひるごはん” — それから introduces lunch at the cafe as the next action.","source":"course.html#lesson-87"},"lesson:92:meaning":{"title":"Please do: 〜てください","front":"What should happen after writing the name?","answer":"Show the card.","context":"","promptAudio":"ここに なまえを かいてください。それから、カードを みせてください。わからない ときは、きいてください。","model":"ここに なまえを かいてください。それから、カードを みせてください。わからない ときは、きいてください。","audioText":"ここに なまえを かいてください。それから、カードを みせてください。わからない ときは、きいてください。","note":"“それから、カードを みせて” — The card is to be shown after the name is written.","source":"course.html#lesson-92"},"lesson:97:meaning":{"title":"Yesterday and last week","front":"What did the speaker do with a friend yesterday?","answer":"Take a walk.","context":"","promptAudio":"きのう、こうえんへ いきました。ともだちと さんぽしました。カフェへは いきませんでした。","model":"きのう、こうえんへ いきました。ともだちと さんぽしました。カフェへは いきませんでした。","audioText":"きのう、こうえんへ いきました。ともだちと さんぽしました。カフェへは いきませんでした。","note":"“ともだちと さんぽしました” — さんぽしました names the shared activity; visiting the cafe is negated.","source":"course.html#lesson-97"},"lesson:102:meaning":{"title":"Telling the time","front":"When does the speaker leave home?","answer":"At 9:10.","context":"","promptAudio":"いま、くじです。じゅぎょうは くじはんからです。わたしは くじじゅっぷんに いえを でます。","model":"いま、くじです。じゅぎょうは くじはんからです。わたしは くじじゅっぷんに いえを でます。","audioText":"いま、くじです。じゅぎょうは くじはんからです。わたしは くじじゅっぷんに いえを でます。","note":"“くじじゅっぷんに いえを でます” — Leaving home is at 9:10; the class begins at 9:30.","source":"course.html#lesson-102"},"lesson:107:meaning":{"title":"Days, months and dates","front":"When is the friend's birthday?","answer":"April 8.","context":"","promptAudio":"わたしの たんじょうびは しがつ はつかです。ともだちの たんじょうびは しがつ ようかです。","model":"わたしの たんじょうびは しがつ はつかです。ともだちの たんじょうびは しがつ ようかです。","audioText":"わたしの たんじょうびは しがつ はつかです。ともだちの たんじょうびは しがつ ようかです。","note":"“ともだちの たんじょうびは しがつ ようか” — しがつ is April and ようか is the eighth day.","source":"course.html#lesson-107"},"lesson:112:meaning":{"title":"Family and people","front":"Where does the older brother work?","answer":"Tokyo.","context":"","promptAudio":"あねは おおさかに すんでいます。あには とうきょうで はたらいています。わたしは りょうしんと すんでいます。","model":"あねは おおさかに すんでいます。あには とうきょうで はたらいています。わたしは りょうしんと すんでいます。","audioText":"あねは おおさかに すんでいます。あには とうきょうで はたらいています。わたしは りょうしんと すんでいます。","note":"“あには とうきょうで はたらいて” — The brother works in Tokyo; the sister lives in Osaka.","source":"course.html#lesson-112"},"lesson:117:meaning":{"title":"Ordering food","front":"When does the customer want the bill?","answer":"Later.","context":"","promptAudio":"ラーメンを ひとつ ください。おみずも おねがいします。おかいけいは あとで おねがいします。","model":"ラーメンを ひとつ ください。おみずも おねがいします。おかいけいは あとで おねがいします。","audioText":"ラーメンを ひとつ ください。おみずも おねがいします。おかいけいは あとで おねがいします。","note":"“おかいけいは あとで” — あとで requests the bill later.","source":"course.html#lesson-117"},"lesson:122:meaning":{"title":"Shopping and money","front":"How much is the shirt?","answer":"3,000 yen.","context":"","promptAudio":"この シャツは さんぜんえんです。ふくろは いりません。カードで はらっても いいですか。","model":"この シャツは さんぜんえんです。ふくろは いりません。カードで はらっても いいですか。","audioText":"この シャツは さんぜんえんです。ふくろは いりません。カードで はらっても いいですか。","note":"“さんぜんえん” — さんぜん is three thousand.","source":"course.html#lesson-122"},"lesson:127:meaning":{"title":"Directions on the street","front":"Where should the listener turn right?","answer":"At the park.","context":"","promptAudio":"えきから まっすぐ いってください。こうえんで みぎに まがってください。カフェは ほんやの となりです。","model":"えきから まっすぐ いってください。こうえんで みぎに まがってください。カフェは ほんやの となりです。","audioText":"えきから まっすぐ いってください。こうえんで みぎに まがってください。カフェは ほんやの となりです。","note":"“こうえんで みぎに” — The turn is at the park; the cafe is next to the bookshop.","source":"course.html#lesson-127"},"lesson:132:meaning":{"title":"Trains, buses and transfers","front":"Where is this train going?","answer":"Kyoto.","context":"","promptAudio":"この でんしゃは きょうとへ いきます。おおさかへ いく ときは、つぎの えきで のりかえてください。","model":"この でんしゃは きょうとへ いきます。おおさかへ いく ときは、つぎの えきで のりかえてください。","audioText":"この でんしゃは きょうとへ いきます。おおさかへ いく ときは、つぎの えきで のりかえてください。","note":"“この でんしゃは きょうとへ” — The train goes to Kyoto; Osaka-bound passengers must change.","source":"course.html#lesson-132"},"lesson:137:meaning":{"title":"Weather and seasons","front":"How is today's temperature described relative to yesterday?","answer":"Today is a little cold after a warm yesterday.","context":"","promptAudio":"きょうは あめです。きのうは あたたかかったですが、きょうは すこし さむいです。かさを もって でかけます。","model":"きょうは あめです。きのうは あたたかかったですが、きょうは すこし さむいです。かさを もって でかけます。","audioText":"きょうは あめです。きのうは あたたかかったですが、きょうは すこし さむいです。かさを もって でかけます。","note":"“きのうは あたたかかったですが、きょうは すこし さむい” — The contrast concerns yesterday's warmth and today's cold.","source":"course.html#lesson-137"},"lesson:142:meaning":{"title":"Likes, hobbies and skill","front":"What is the friend good at?","answer":"Cooking.","context":"","promptAudio":"わたしは おんがくが すきです。ギターを すこし ひけます。ともだちは りょうりが じょうずです。","model":"わたしは おんがくが すきです。ギターを すこし ひけます。ともだちは りょうりが じょうずです。","audioText":"わたしは おんがくが すきです。ギターを すこし ひけます。ともだちは りょうりが じょうずです。","note":"“ともだちは りょうりが じょうず” — Cooking is the friend's skill; the speaker can play a little guitar.","source":"course.html#lesson-142"},"lesson:147:meaning":{"title":"A day in the life","front":"What does the speaker do after breakfast?","answer":"Go to work.","context":"","promptAudio":"あさ ろくじに おきます。あさごはんを たべて、しごとへ いきます。よるは すこし にほんごを べんきょうします。","model":"あさ ろくじに おきます。あさごはんを たべて、しごとへ いきます。よるは すこし にほんごを べんきょうします。","audioText":"あさ ろくじに おきます。あさごはんを たべて、しごとへ いきます。よるは すこし にほんごを べんきょうします。","note":"“あさごはんを たべて、しごとへ” — Eating breakfast comes before going to work.","source":"course.html#lesson-147"},"lesson:152:meaning":{"title":"The て-form: joining actions","front":"Who receives the photographs?","answer":"Family living far away.","context":"","promptAudio":"土曜日は朝ご飯を食べて、友達に会って、一緒に市場へ行きました。魚を買って、家で料理を作りました。料理の写真を撮って、遠くに住む家族に送りました。","model":"土曜日は朝ご飯を食べて、友達に会って、一緒に市場へ行きました。魚を買って、家で料理を作りました。料理の写真を撮って、遠くに住む家族に送りました。","audioText":"土曜日は朝ご飯を食べて、友達に会って、一緒に市場へ行きました。魚を買って、家で料理を作りました。料理の写真を撮って、遠くに住む家族に送りました。","note":"“遠くに住む家族に送りました” — The distant family is the recipient, following cooking and photographing.","source":"course.html#lesson-152"},"lesson:157:meaning":{"title":"Doing now: 〜ている","front":"Where is the narrator's friend?","answer":"Already sitting near the window.","context":"","promptAudio":"図書館では、学生が静かに本を読んでいます。入り口では、職員が新しい利用者に説明しています。私は席を探していますが、友達はもう窓の近くに座っています。","model":"図書館では、学生が静かに本を読んでいます。入り口では、職員が新しい利用者に説明しています。私は席を探していますが、友達はもう窓の近くに座っています。","audioText":"図書館では、学生が静かに本を読んでいます。入り口では、職員が新しい利用者に説明しています。私は席を探していますが、友達はもう窓の近くに座っています。","note":"“友達はもう窓の近くに座っています” — もう distinguishes the friend's already-seated state from the narrator's search.","source":"course.html#lesson-157"},"lesson:162:meaning":{"title":"May I? You must not","front":"What should visitors do with large luggage?","answer":"Leave it at the entrance.","context":"","promptAudio":"この部屋では写真を撮ってもいいですが、食べ物を持ち込んではいけません。大きな荷物は入り口で預けてください。分からないときは、係の人に聞いてもかまいません。","model":"この部屋では写真を撮ってもいいですが、食べ物を持ち込んではいけません。大きな荷物は入り口で預けてください。分からないときは、係の人に聞いてもかまいません。","audioText":"この部屋では写真を撮ってもいいですが、食べ物を持ち込んではいけません。大きな荷物は入り口で預けてください。分からないときは、係の人に聞いてもかまいません。","note":"“大きな荷物は入り口で預けて” — The instruction specifies the entrance as the place to leave large luggage.","source":"course.html#lesson-162"},"lesson:167:meaning":{"title":"Please do not","front":"Which route should people going to the station take?","answer":"The narrow road on the right.","context":"","promptAudio":"工事中のため、この道を通らないでください。駅へ行く方は、右の細い道をお進みください。夜は暗くなるので、足元に気を付けてください。","model":"工事中のため、この道を通らないでください。駅へ行く方は、右の細い道をお進みください。夜は暗くなるので、足元に気を付けてください。","audioText":"工事中のため、この道を通らないでください。駅へ行く方は、右の細い道をお進みください。夜は暗くなるので、足元に気を付けてください。","note":"“右の細い道” — The notice redirects station-bound pedestrians to the right.","source":"course.html#lesson-167"},"lesson:172:meaning":{"title":"Can do: the potential form","front":"What may happen to a telephone reservation at a busy time?","answer":"The response may be delayed.","context":"","promptAudio":"この店ではカードが使えます。ただし、料理によっては持ち帰ることができません。予約は電話でもできますが、混んでいる時間は返事が遅れる場合があります。","model":"この店ではカードが使えます。ただし、料理によっては持ち帰ることができません。予約は電話でもできますが、混んでいる時間は返事が遅れる場合があります。","audioText":"この店ではカードが使えます。ただし、料理によっては持ち帰ることができません。予約は電話でもできますが、混んでいる時間は返事が遅れる場合があります。","note":"“返事が遅れる場合があります” — The limitation concerns response time, not whether telephone reservations exist.","source":"course.html#lesson-172"},"lesson:177:meaning":{"title":"Wanting to do something","front":"What has NOT been decided yet?","answer":"The travel date.","context":"","promptAudio":"来月、友達と海へ行きたいと思っています。泳ぎたい友達もいますが、私は近くの町を歩いてみたいです。まだ日にちを決めていないので、みんなの予定を聞くつもりです。","model":"来月、友達と海へ行きたいと思っています。泳ぎたい友達もいますが、私は近くの町を歩いてみたいです。まだ日にちを決めていないので、みんなの予定を聞くつもりです。","audioText":"来月、友達と海へ行きたいと思っています。泳ぎたい友達もいますが、私は近くの町を歩いてみたいです。まだ日にちを決めていないので、みんなの予定を聞くつもりです。","note":"“まだ日にちを決めていない” — The date remains open, so they will ask about everyone's availability.","source":"course.html#lesson-177"},"lesson:182:meaning":{"title":"Because: から and ので","front":"What happened to the outdoor information session?","answer":"It was cancelled because the rain intensified.","context":"","promptAudio":"雨が強くなったので、屋外の説明会は中止になりました。室内の会場は狭いから、二回に分けて行います。参加する方は、案内の時間を確認してください。","model":"雨が強くなったので、屋外の説明会は中止になりました。室内の会場は狭いから、二回に分けて行います。参加する方は、案内の時間を確認してください。","audioText":"雨が強くなったので、屋外の説明会は中止になりました。室内の会場は狭いから、二回に分けて行います。参加する方は、案内の時間を確認してください。","note":"“屋外の説明会は中止” — The outdoor session is cancelled; the indoor arrangement is split because of limited space.","source":"course.html#lesson-182"},"lesson:187:meaning":{"title":"But: が and けど","front":"What is the drawback of the quiet hotel?","answer":"It is a twenty-minute walk from the station.","context":"","promptAudio":"駅に近いホテルは便利ですが、夜は少しにぎやかです。もう一つのホテルは静かだけど、駅から歩いて二十分かかります。私は早朝の電車に乗るので、駅に近い方を選びました。","model":"駅に近いホテルは便利ですが、夜は少しにぎやかです。もう一つのホテルは静かだけど、駅から歩いて二十分かかります。私は早朝の電車に乗るので、駅に近い方を選びました。","audioText":"駅に近いホテルは便利ですが、夜は少しにぎやかです。もう一つのホテルは静かだけど、駅から歩いて二十分かかります。私は早朝の電車に乗るので、駅に近い方を選びました。","note":"“駅から歩いて二十分” — The quiet option requires a longer walk; inability to use it is not stated.","source":"course.html#lesson-187"},"lesson:192:meaning":{"title":"Comparing two things","front":"What advantage does the speaker attribute to the subway?","answer":"It is faster.","context":"","promptAudio":"兄はバスの方が安いと言いますが、私は地下鉄の方が早いと思います。荷物が多い日は、乗り換えの少ないバスも便利です。何を比べるかによって、よい方法は変わります。","model":"兄はバスの方が安いと言いますが、私は地下鉄の方が早いと思います。荷物が多い日は、乗り換えの少ないバスも便利です。何を比べるかによって、よい方法は変わります。","audioText":"兄はバスの方が安いと言いますが、私は地下鉄の方が早いと思います。荷物が多い日は、乗り換えの少ないバスも便利です。何を比べるかによって、よい方法は変わります。","note":"“地下鉄の方が早い” — Speed is the speaker's subway comparison; cheapness and fewer transfers concern the bus.","source":"course.html#lesson-192"},"lesson:197:meaning":{"title":"Counting things","front":"How many spoons are requested?","answer":"Four.","context":"","promptAudio":"四人で店に入り、飲み物を四つとケーキを二つ注文しました。ケーキは二人で一つずつ分けます。スプーンも四本お願いしました。","model":"四人で店に入り、飲み物を四つとケーキを二つ注文しました。ケーキは二人で一つずつ分けます。スプーンも四本お願いしました。","audioText":"四人で店に入り、飲み物を四つとケーキを二つ注文しました。ケーキは二人で一つずつ分けます。スプーンも四本お願いしました。","note":"“スプーンも四本” — 四本 counts four spoons, matching four people.","source":"course.html#lesson-197"},"lesson:202:meaning":{"title":"Have you ever…?","front":"When has the friend NOT climbed the mountain?","answer":"In winter.","context":"","promptAudio":"友達は山に登ったことがありますが、冬には行ったことがありません。私はまだ一度も登ったことがないので、初めての人向けの道を一緒に探しています。","model":"友達は山に登ったことがありますが、冬には行ったことがありません。私はまだ一度も登ったことがないので、初めての人向けの道を一緒に探しています。","audioText":"友達は山に登ったことがありますが、冬には行ったことがありません。私はまだ一度も登ったことがないので、初めての人向けの道を一緒に探しています。","note":"“冬には行ったことがありません” — The friend has climbed before, but not in winter.","source":"course.html#lesson-202"},"lesson:207:meaning":{"title":"While doing: 〜ながら","front":"Why does the narrator pause the music?","answer":"To concentrate on transfer announcements.","context":"","promptAudio":"私は通勤中、音楽を聞きながら電車に乗っています。ただ、乗り換えの案内を聞くときは音楽を止めます。同時にできることでも、注意が必要な場面では一つに集中したいからです。","model":"私は通勤中、音楽を聞きながら電車に乗っています。ただ、乗り換えの案内を聞くときは音楽を止めます。同時にできることでも、注意が必要な場面では一つに集中したいからです。","audioText":"私は通勤中、音楽を聞きながら電車に乗っています。ただ、乗り換えの案内を聞くときは音楽を止めます。同時にできることでも、注意が必要な場面では一つに集中したいからです。","note":"“乗り換えの案内を聞くとき” — The pause is tied to a situation needing attention.","source":"course.html#lesson-207"},"lesson:212:meaning":{"title":"Oops: 〜てしまう","front":"What does the narrator do immediately after sending the photo to the wrong person?","answer":"Explain the mistake and ask for deletion.","context":"","promptAudio":"友達に送る写真を、別の人に送ってしまいました。すぐに間違いを伝えて、削除をお願いしました。それから、写真を送る前に相手の名前を確認することにしました。","model":"友達に送る写真を、別の人に送ってしまいました。すぐに間違いを伝えて、削除をお願いしました。それから、写真を送る前に相手の名前を確認することにしました。","audioText":"友達に送る写真を、別の人に送ってしまいました。すぐに間違いを伝えて、削除をお願いしました。それから、写真を送る前に相手の名前を確認することにしました。","note":"“すぐに間違いを伝えて、削除をお願い” — The immediate repair comes before the new checking habit.","source":"course.html#lesson-212"},"lesson:217:meaning":{"title":"Do it in advance: 〜ておく","front":"What was already checked before departure day?","answer":"The route to the station.","context":"","promptAudio":"明日は朝早く出るので、今夜のうちに荷物をまとめておきます。駅までの道も調べておきました。でも、天気は変わるかもしれないので、出発前にもう一度確認します。","model":"明日は朝早く出るので、今夜のうちに荷物をまとめておきます。駅までの道も調べておきました。でも、天気は変わるかもしれないので、出発前にもう一度確認します。","audioText":"明日は朝早く出るので、今夜のうちに荷物をまとめておきます。駅までの道も調べておきました。でも、天気は変わるかもしれないので、出発前にもう一度確認します。","note":"“駅までの道も調べておきました” — The route has been researched; the weather will be checked again.","source":"course.html#lesson-217"},"lesson:222:meaning":{"title":"Try it: 〜てみる","front":"How did the food compare with the narrator's expectation?","answer":"It was less spicy than expected.","context":"","promptAudio":"知らない料理だったので、まず少し食べてみました。思ったより辛くありませんでした。友達にも勧めましたが、辛い物が苦手だと聞いたので、別の料理も紹介しました。","model":"知らない料理だったので、まず少し食べてみました。思ったより辛くありませんでした。友達にも勧めましたが、辛い物が苦手だと聞いたので、別の料理も紹介しました。","audioText":"知らない料理だったので、まず少し食べてみました。思ったより辛くありませんでした。友達にも勧めましたが、辛い物が苦手だと聞いたので、別の料理も紹介しました。","note":"“思ったより辛くありませんでした” — The narrator tried it and found it less spicy, while the friend's preference differed.","source":"course.html#lesson-222"},"lesson:227:meaning":{"title":"Looks like: 〜そう","front":"What does the narrator decide to bring?","answer":"An umbrella.","context":"","promptAudio":"窓から見ると、雨が降りそうです。友達は「駅に着くまで大丈夫そう」と言いましたが、私は傘を持って出ることにしました。空の様子だけでは、いつ降り始めるかは分かりません。","model":"窓から見ると、雨が降りそうです。友達は「駅に着くまで大丈夫そう」と言いましたが、私は傘を持って出ることにしました。空の様子だけでは、いつ降り始めるかは分かりません。","audioText":"窓から見ると、雨が降りそうです。友達は「駅に着くまで大丈夫そう」と言いましたが、私は傘を持って出ることにしました。空の様子だけでは、いつ降り始めるかは分かりません。","note":"“私は傘を持って出る” — The narrator brings an umbrella despite the friend's optimistic impression.","source":"course.html#lesson-227"},"lesson:232:meaning":{"title":"I heard / it seems: 〜らしい and 〜みたい","front":"What does the narrator plan to do at the weekend?","answer":"Visit and check the new bakery.","context":"","promptAudio":"駅前に新しいパン屋ができたらしいです。外から見ると、小さなカフェもあるみたいです。まだ中に入っていないので、週末に確かめてみようと思います。","model":"駅前に新しいパン屋ができたらしいです。外から見ると、小さなカフェもあるみたいです。まだ中に入っていないので、週末に確かめてみようと思います。","audioText":"駅前に新しいパン屋ができたらしいです。外から見ると、小さなカフェもあるみたいです。まだ中に入っていないので、週末に確かめてみようと思います。","note":"“週末に確かめてみよう” — The narrator has not gone inside and plans to check personally.","source":"course.html#lesson-232"},"lesson:237:meaning":{"title":"The explanation 〜んです","front":"What explanation does the late friend give?","answer":"The train stopped.","context":"","promptAudio":"友達が遅れて来たので、理由を聞きました。「電車が止まったんです」と説明してくれました。私は「それは大変でしたね」と答え、予定を少し変えることにしました。","model":"友達が遅れて来たので、理由を聞きました。「電車が止まったんです」と説明してくれました。私は「それは大変でしたね」と答え、予定を少し変えることにしました。","audioText":"友達が遅れて来たので、理由を聞きました。「電車が止まったんです」と説明してくれました。私は「それは大変でしたね」と答え、予定を少し変えることにしました。","note":"“電車が止まったんです” — んです supplies the background for the late arrival.","source":"course.html#lesson-237"},"lesson:242:meaning":{"title":"When: 〜とき","front":"Where does the narrator go first after losing the wallet?","answer":"Back to the hotel.","context":"","promptAudio":"旅行中に財布をなくしたとき、まず泊まっていたホテルに戻りました。見つからなかったので、最後に使った店へ連絡しました。困ったときは、覚えていることを順に整理すると、次の行動を決めやすくなります。","model":"旅行中に財布をなくしたとき、まず泊まっていたホテルに戻りました。見つからなかったので、最後に使った店へ連絡しました。困ったときは、覚えていることを順に整理すると、次の行動を決めやすくなります。","audioText":"旅行中に財布をなくしたとき、まず泊まっていたホテルに戻りました。見つからなかったので、最後に使った店へ連絡しました。困ったときは、覚えていることを順に整理すると、次の行動を決めやすくなります。","note":"“まず泊まっていたホテルに戻りました” — まず establishes the hotel as the first search location.","source":"course.html#lesson-242"},"lesson:247:meaning":{"title":"Your first long turn","front":"Where does the narrator have lunch?","answer":"In the park recommended by the shop worker.","context":"","promptAudio":"先週、初めて一人で小さな町を訪ねました。道に迷いましたが、店の人が地図を見せてくれました。その後、教えてもらった公園で昼ご飯を食べました。予定どおりではありませんでしたが、人と話すきっかけになりました。","model":"先週、初めて一人で小さな町を訪ねました。道に迷いましたが、店の人が地図を見せてくれました。その後、教えてもらった公園で昼ご飯を食べました。予定どおりではありませんでしたが、人と話すきっかけになりました。","audioText":"先週、初めて一人で小さな町を訪ねました。道に迷いましたが、店の人が地図を見せてくれました。その後、教えてもらった公園で昼ご飯を食べました。予定どおりではありませんでしたが、人と話すきっかけになりました。","note":"“教えてもらった公園で昼ご飯” — The helpful directions lead to lunch at the park.","source":"course.html#lesson-247"},"lesson:252:meaning":{"title":"The passive: it was done to me","front":"Why does the narrator miss the train?","answer":"They are explaining directions to a stranger.","context":"","promptAudio":"朝、駅で知らない人に道を聞かれました。説明している間に電車が出てしまいました。会社で事情を話すと、同僚は「大変でしたね。でも、その人は助かったでしょう」と言いました。遅刻は困りましたが、少し気持ちが軽くなりました。","model":"朝、駅で知らない人に道を聞かれました。説明している間に電車が出てしまいました。会社で事情を話すと、同僚は「大変でしたね。でも、その人は助かったでしょう」と言いました。遅刻は困りましたが、少し気持ちが軽くなりました。","audioText":"朝、駅で知らない人に道を聞かれました。説明している間に電車が出てしまいました。会社で事情を話すと、同僚は「大変でしたね。でも、その人は助かったでしょう」と言いました。遅刻は困りましたが、少し気持ちが軽くなりました。","note":"“説明している間に電車が出て” — The train leaves while the narrator is helping with directions.","source":"course.html#lesson-252"},"lesson:257:meaning":{"title":"The causative: make or let someone do","front":"What task does the mother let the child do?","answer":"Wash vegetables.","context":"","promptAudio":"子どもが一人で料理をしたいと言ったので、母親は野菜を洗わせました。包丁を使う前に、安全な持ち方を一緒に確認しました。全部を代わりにするのではなく、できる部分を任せたかったのです。時間はかかりましたが、子どもは自分で作ったスープを喜んで食べました。","model":"子どもが一人で料理をしたいと言ったので、母親は野菜を洗わせました。包丁を使う前に、安全な持ち方を一緒に確認しました。全部を代わりにするのではなく、できる部分を任せたかったのです。時間はかかりましたが、子どもは自分で作ったスープを喜んで食べました。","audioText":"子どもが一人で料理をしたいと言ったので、母親は野菜を洗わせました。包丁を使う前に、安全な持ち方を一緒に確認しました。全部を代わりにするのではなく、できる部分を任せたかったのです。時間はかかりましたが、子どもは自分で作ったスープを喜んで食べました。","note":"“母親は野菜を洗わせました” — The mother gives a manageable task and checks safety before knife use.","source":"course.html#lesson-257"},"lesson:262:meaning":{"title":"Made to do: causative passive","front":"What does the narrator now understand about the reports?","answer":"They provided background for the assigned work.","context":"","promptAudio":"新人のころ、私は毎朝、長い報告書を読まされました。当時は意味が分からず、不満に思っていました。後で、担当する仕事の背景を知るためだったと聞きました。目的は理解できましたが、最初に説明してもらえたら、もっと前向きに取り組めたと思います。","model":"新人のころ、私は毎朝、長い報告書を読まされました。当時は意味が分からず、不満に思っていました。後で、担当する仕事の背景を知るためだったと聞きました。目的は理解できましたが、最初に説明してもらえたら、もっと前向きに取り組めたと思います。","audioText":"新人のころ、私は毎朝、長い報告書を読まされました。当時は意味が分からず、不満に思っていました。後で、担当する仕事の背景を知るためだったと聞きました。目的は理解できましたが、最初に説明してもらえたら、もっと前向きに取り組めたと思います。","note":"“担当する仕事の背景を知るため” — The purpose becomes clear later; the objection is to its not being explained initially.","source":"course.html#lesson-262"},"lesson:267:meaning":{"title":"If: 〜ば","front":"What alternative is suggested in bad weather?","answer":"Leave earlier and take a bus.","context":"","promptAudio":"この町では、自転車を使えば駅まで十分で行けます。ただし、雨の日は道が滑りやすくなります。時間だけで選ばず、天気も確認するとよいでしょう。天気が悪ければ、少し早く出てバスを使う方法もあります。","model":"この町では、自転車を使えば駅まで十分で行けます。ただし、雨の日は道が滑りやすくなります。時間だけで選ばず、天気も確認するとよいでしょう。天気が悪ければ、少し早く出てバスを使う方法もあります。","audioText":"この町では、自転車を使えば駅まで十分で行けます。ただし、雨の日は道が滑りやすくなります。時間だけで選ばず、天気も確認するとよいでしょう。天気が悪ければ、少し早く出てバスを使う方法もあります。","note":"“少し早く出てバスを使う” — The alternative adjusts departure and transport to the weather.","source":"course.html#lesson-267"},"lesson:272:meaning":{"title":"If / when: 〜たら","front":"Why check whether the other person has left home?","answer":"To coordinate a possible change of plan.","context":"","promptAudio":"週末、友人と公園で会う予定です。雨が降ったら、近くの美術館へ行くことにしました。朝は晴れていても、出かける前に連絡を取り合います。予定を変える場合は、相手がもう家を出ていないか確認したいからです。","model":"週末、友人と公園で会う予定です。雨が降ったら、近くの美術館へ行くことにしました。朝は晴れていても、出かける前に連絡を取り合います。予定を変える場合は、相手がもう家を出ていないか確認したいからです。","audioText":"週末、友人と公園で会う予定です。雨が降ったら、近くの美術館へ行くことにしました。朝は晴れていても、出かける前に連絡を取り合います。予定を変える場合は、相手がもう家を出ていないか確認したいからです。","note":"“相手がもう家を出ていないか” — A change should account for whether the other person is already travelling.","source":"course.html#lesson-272"},"lesson:277:meaning":{"title":"Speaking of: 〜なら","front":"When does the narrator plan the suggested walk?","answer":"The morning after arriving.","context":"","promptAudio":"「京都へ行くなら、朝早く出るといいですよ」と友人に言われました。混んでいない時間に歩けるからだそうです。ただ、私は夜に着く予定だったので、翌朝に散歩することにしました。助言は参考になりますが、自分の予定に合わせて使うことも大切です。","model":"「京都へ行くなら、朝早く出るといいですよ」と友人に言われました。混んでいない時間に歩けるからだそうです。ただ、私は夜に着く予定だったので、翌朝に散歩することにしました。助言は参考になりますが、自分の予定に合わせて使うことも大切です。","audioText":"「京都へ行くなら、朝早く出るといいですよ」と友人に言われました。混んでいない時間に歩けるからだそうです。ただ、私は夜に着く予定だったので、翌朝に散歩することにしました。助言は参考になりますが、自分の予定に合わせて使うことも大切です。","note":"“翌朝に散歩” — The narrator adapts the advice to a night-time arrival.","source":"course.html#lesson-277"},"lesson:282:meaning":{"title":"Even if: 〜ても","front":"What information will be given before arranging the optional taxi?","answer":"The cost.","context":"","promptAudio":"会場が駅から遠くても、この店で集まりたいという人が多くいました。静かで、食事の選択肢も多いからです。一方、歩くのが難しい参加者もいます。そこで、希望者には駅からタクシーを手配し、費用を事前に知らせることにしました。","model":"会場が駅から遠くても、この店で集まりたいという人が多くいました。静かで、食事の選択肢も多いからです。一方、歩くのが難しい参加者もいます。そこで、希望者には駅からタクシーを手配し、費用を事前に知らせることにしました。","audioText":"会場が駅から遠くても、この店で集まりたいという人が多くいました。静かで、食事の選択肢も多いからです。一方、歩くのが難しい参加者もいます。そこで、希望者には駅からタクシーを手配し、費用を事前に知らせることにしました。","note":"“費用を事前に知らせる” — Advance cost information lets those needing transport make a choice.","source":"course.html#lesson-282"},"lesson:287:meaning":{"title":"Make a habit, reach a state","front":"What happens on a busy day?","answer":"The listening routine is shortened to one minute.","context":"","promptAudio":"日本語を聞く時間を増やすために、朝食の後で短い番組を聞くようにしています。最初は内容がほとんど分かりませんでしたが、同じ話題を選ぶうちに、よく使う言葉が聞き取れるようになりました。忙しい日は一分だけにして、無理なく続けています。","model":"日本語を聞く時間を増やすために、朝食の後で短い番組を聞くようにしています。最初は内容がほとんど分かりませんでしたが、同じ話題を選ぶうちに、よく使う言葉が聞き取れるようになりました。忙しい日は一分だけにして、無理なく続けています。","audioText":"日本語を聞く時間を増やすために、朝食の後で短い番組を聞くようにしています。最初は内容がほとんど分かりませんでしたが、同じ話題を選ぶうちに、よく使う言葉が聞き取れるようになりました。忙しい日は一分だけにして、無理なく続けています。","note":"“忙しい日は一分だけ” — A manageable shorter session helps maintain the routine.","source":"course.html#lesson-287"},"lesson:292:meaning":{"title":"Purpose: ために and ように","front":"Why is an explanation posted at the library entrance?","answer":"So users understand the reason for the seating change.","context":"","promptAudio":"図書館は、利用者が落ち着いて読めるように、話し合い用の席と静かな席を分けました。職員は、変更の理由を知ってもらうために、入り口に説明を出しました。席が足りない時間もあるので、利用状況を見ながら調整する予定です。","model":"図書館は、利用者が落ち着いて読めるように、話し合い用の席と静かな席を分けました。職員は、変更の理由を知ってもらうために、入り口に説明を出しました。席が足りない時間もあるので、利用状況を見ながら調整する予定です。","audioText":"図書館は、利用者が落ち着いて読めるように、話し合い用の席と静かな席を分けました。職員は、変更の理由を知ってもらうために、入り口に説明を出しました。席が足りない時間もあるので、利用状況を見ながら調整する予定です。","note":"“変更の理由を知ってもらうため” — The posted information explains the change; usage will still be monitored.","source":"course.html#lesson-292"},"lesson:297:meaning":{"title":"Negotiate politely","front":"What do the friends decide to do this time?","answer":"Stay near a lake and enjoy the scenery.","context":"","promptAudio":"友人と旅行の予定を立てました。私は山へ行きたかったのですが、友人は足を痛めていました。「短い道ならどうですか」と聞く前に、どのくらい歩けるか確認しました。相談した結果、今回は湖の近くに泊まり、景色を楽しむことにしました。","model":"友人と旅行の予定を立てました。私は山へ行きたかったのですが、友人は足を痛めていました。「短い道ならどうですか」と聞く前に、どのくらい歩けるか確認しました。相談した結果、今回は湖の近くに泊まり、景色を楽しむことにしました。","audioText":"友人と旅行の予定を立てました。私は山へ行きたかったのですが、友人は足を痛めていました。「短い道ならどうですか」と聞く前に、どのくらい歩けるか確認しました。相談した結果、今回は湖の近くに泊まり、景色を楽しむことにしました。","note":"“今回は湖の近くに泊まり” — The final plan follows a conversation about the friend's needs.","source":"course.html#lesson-297"},"lesson:302:meaning":{"title":"That explains it: 〜わけだ","front":"Why are reservation holders shown to a table quickly?","answer":"Seats have been prepared separately for them.","context":"","promptAudio":"予約した店の前には長い列ができていました。しかし、受付で名前を伝えると、すぐ席に案内されました。予約客の席は別に用意されていたのです。それで友人が「並ばなくていいわけですね」と言いました。見えた状況だけでは、仕組みまでは分かりませんでした。","model":"予約した店の前には長い列ができていました。しかし、受付で名前を伝えると、すぐ席に案内されました。予約客の席は別に用意されていたのです。それで友人が「並ばなくていいわけですね」と言いました。見えた状況だけでは、仕組みまでは分かりませんでした。","audioText":"予約した店の前には長い列ができていました。しかし、受付で名前を伝えると、すぐ席に案内されました。予約客の席は別に用意されていたのです。それで友人が「並ばなくていいわけですね」と言いました。見えた状況だけでは、仕組みまでは分かりませんでした。","note":"“予約客の席は別に用意” — The explanation concerns a separate arrangement, not a general ban on walk-ins.","source":"course.html#lesson-302"},"lesson:307:meaning":{"title":"Should be: 〜はずだ","front":"What new information changes the expected delivery date?","answer":"Weather has delayed the shipment.","context":"","promptAudio":"荷物は昨日発送されたので、今日届くはずだと思っていました。ところが、配送状況を見ると、天候の影響で遅れていました。予定に基づく予想は間違いとは限りませんが、新しい情報が入ったら見直す必要があります。私は受け取りの予定を明日に変えました。","model":"荷物は昨日発送されたので、今日届くはずだと思っていました。ところが、配送状況を見ると、天候の影響で遅れていました。予定に基づく予想は間違いとは限りませんが、新しい情報が入ったら見直す必要があります。私は受け取りの予定を明日に変えました。","audioText":"荷物は昨日発送されたので、今日届くはずだと思っていました。ところが、配送状況を見ると、天候の影響で遅れていました。予定に基づく予想は間違いとは限りませんが、新しい情報が入ったら見直す必要があります。私は受け取りの予定を明日に変えました。","note":"“天候の影響で遅れて” — Dispatch happened yesterday, but the new tracking information reports a delay.","source":"course.html#lesson-307"},"lesson:312:meaning":{"title":"Certainty and possibility","front":"What does the narrator still not know about the new shop?","answer":"Its name.","context":"","promptAudio":"駅前に新しい店ができるらしいと聞きました。まだ看板はありませんが、工事の人が飲食店だと話していたそうです。友人は人気店に違いないと言いますが、私は店の名前も分からないうちは判断できないと思います。情報の確かさを分けて考えたいのです。","model":"駅前に新しい店ができるらしいと聞きました。まだ看板はありませんが、工事の人が飲食店だと話していたそうです。友人は人気店に違いないと言いますが、私は店の名前も分からないうちは判断できないと思います。情報の確かさを分けて考えたいのです。","audioText":"駅前に新しい店ができるらしいと聞きました。まだ看板はありませんが、工事の人が飲食店だと話していたそうです。友人は人気店に違いないと言いますが、私は店の名前も分からないうちは判断できないと思います。情報の確かさを分けて考えたいのです。","note":"“店の名前も分からない” — The unknown identity is a reason not to accept the friend's strong prediction yet.","source":"course.html#lesson-312"},"lesson:317:meaning":{"title":"No way to: 〜ようがない","front":"What information does the narrator use to continue searching for the umbrella?","answer":"The places and times where it was used.","context":"","promptAudio":"忘れ物の傘を探しましたが、色も形も覚えていませんでした。駅員に聞こうにも、特徴を説明しようがありません。そこで、使った場所と時間を整理し、心当たりの店に問い合わせました。全部分からなくても、分かっている情報から探す方法はありました。","model":"忘れ物の傘を探しましたが、色も形も覚えていませんでした。駅員に聞こうにも、特徴を説明しようがありません。そこで、使った場所と時間を整理し、心当たりの店に問い合わせました。全部分からなくても、分かっている情報から探す方法はありました。","audioText":"忘れ物の傘を探しましたが、色も形も覚えていませんでした。駅員に聞こうにも、特徴を説明しようがありません。そこで、使った場所と時間を整理し、心当たりの店に問い合わせました。全部分からなくても、分かっている情報から探す方法はありました。","note":"“使った場所と時間を整理” — Some descriptive details are missing, but location and time remain useful.","source":"course.html#lesson-317"},"lesson:322:meaning":{"title":"Only and nothing but","front":"Who may visit the vegetable-only restaurant?","answer":"People curious about new tastes, as well as people who avoid meat.","context":"","promptAudio":"この店のメニューには、野菜の料理しかありません。店主は、野菜だけでも満足できる食事を作りたいと話します。肉を食べない客ばかりが来るわけではなく、新しい味を試したい人も訪れます。「しか」「だけ」「ばかり」は似ていますが、話し手の見方は同じではありません。","model":"この店のメニューには、野菜の料理しかありません。店主は、野菜だけでも満足できる食事を作りたいと話します。肉を食べない客ばかりが来るわけではなく、新しい味を試したい人も訪れます。「しか」「だけ」「ばかり」は似ていますが、話し手の見方は同じではありません。","audioText":"この店のメニューには、野菜の料理しかありません。店主は、野菜だけでも満足できる食事を作りたいと話します。肉を食べない客ばかりが来るわけではなく、新しい味を試したい人も訪れます。「しか」「だけ」「ばかり」は似ていますが、話し手の見方は同じではありません。","note":"“新しい味を試したい人も” — The menu is limited to vegetables, but the customers' motivations are not identical.","source":"course.html#lesson-322"},"lesson:327:meaning":{"title":"To the extent: 〜ほど and 〜くらい","front":"What helps the narrator become slightly calmer during the presentation?","answer":"Saying the first sentence.","context":"","promptAudio":"初めて一人で発表したときは、声が出なくなるほど緊張しました。それでも、最初の一文を言うと、少し落ち着きました。友人は「私も同じくらい緊張する」と言ってくれました。緊張の大きさは比べられても、対処の仕方は人によって違うようです。","model":"初めて一人で発表したときは、声が出なくなるほど緊張しました。それでも、最初の一文を言うと、少し落ち着きました。友人は「私も同じくらい緊張する」と言ってくれました。緊張の大きさは比べられても、対処の仕方は人によって違うようです。","audioText":"初めて一人で発表したときは、声が出なくなるほど緊張しました。それでも、最初の一文を言うと、少し落ち着きました。友人は「私も同じくらい緊張する」と言ってくれました。緊張の大きさは比べられても、対処の仕方は人によって違うようです。","note":"“最初の一文を言うと、少し落ち着き” — The first spoken step eases the nerves; the friend reports similar nervousness.","source":"course.html#lesson-327"},"lesson:332:meaning":{"title":"Although: 〜のに","front":"What do the cinema staff provide after the machine stops?","answer":"Tickets that can be used on another day.","context":"","promptAudio":"楽しみにしていた映画を見に行ったのに、途中で機械が止まりました。係員は謝り、別の日に使える券を配りました。最後まで見られなかったのは残念ですが、対応には納得しました。一つの出来事について、残念な点と評価できる点の両方を伝えられます。","model":"楽しみにしていた映画を見に行ったのに、途中で機械が止まりました。係員は謝り、別の日に使える券を配りました。最後まで見られなかったのは残念ですが、対応には納得しました。一つの出来事について、残念な点と評価できる点の両方を伝えられます。","audioText":"楽しみにしていた映画を見に行ったのに、途中で機械が止まりました。係員は謝り、別の日に使える券を配りました。最後まで見られなかったのは残念ですが、対応には納得しました。一つの出来事について、残念な点と評価できる点の両方を伝えられます。","note":"“別の日に使える券” — The narrator is disappointed but accepts this response.","source":"course.html#lesson-332"},"lesson:337:meaning":{"title":"Thanks to / because of: 〜おかげで and 〜せいで","front":"What will the narrator improve next time?","answer":"Their own way of sharing necessary information.","context":"","promptAudio":"締め切りに間に合ったのは、同僚が資料を確認してくれたおかげです。ただ、作業が遅れた原因は、私が必要な情報を早く共有しなかったことでした。感謝を伝えると同時に、次回は自分の連絡方法を改善しようと思います。人の助けと自分の課題を分けて考えることができました。","model":"締め切りに間に合ったのは、同僚が資料を確認してくれたおかげです。ただ、作業が遅れた原因は、私が必要な情報を早く共有しなかったことでした。感謝を伝えると同時に、次回は自分の連絡方法を改善しようと思います。人の助けと自分の課題を分けて考えることができました。","audioText":"締め切りに間に合ったのは、同僚が資料を確認してくれたおかげです。ただ、作業が遅れた原因は、私が必要な情報を早く共有しなかったことでした。感謝を伝えると同時に、次回は自分の連絡方法を改善しようと思います。人の助けと自分の課題を分けて考えることができました。","note":"“自分の連絡方法を改善” — The narrator distinguishes gratitude for help from responsibility for earlier delays.","source":"course.html#lesson-337"},"lesson:342:meaning":{"title":"Every time and while you are at it","front":"What assumption does the narrator avoid when submitting documents?","answer":"That every visit will require exactly the same checks.","context":"","promptAudio":"役所へ行くついでに、近くの郵便局にも寄ることにしました。ただし、書類を出すたびに窓口で確認することが違うので、前回と同じだと思い込まないようにしています。用事をまとめると便利ですが、一つ一つの条件は確かめる必要があります。","model":"役所へ行くついでに、近くの郵便局にも寄ることにしました。ただし、書類を出すたびに窓口で確認することが違うので、前回と同じだと思い込まないようにしています。用事をまとめると便利ですが、一つ一つの条件は確かめる必要があります。","audioText":"役所へ行くついでに、近くの郵便局にも寄ることにしました。ただし、書類を出すたびに窓口で確認することが違うので、前回と同じだと思い込まないようにしています。用事をまとめると便利ですが、一つ一つの条件は確かめる必要があります。","note":"“前回と同じだと思い込まない” — Conditions can differ at each submission even when errands are combined.","source":"course.html#lesson-342"},"lesson:347:meaning":{"title":"Tell it with nuance","front":"Where does the narrator find a place they like?","answer":"On a calm path beside the river.","context":"","promptAudio":"友人に勧められた町へ行きました。駅前は思ったほど静かではありませんでしたが、少し歩くと川沿いに落ち着いた道がありました。期待と違う点もありましたが、歩いてみたおかげで、自分の好きな場所を見つけられました。誰かの評価だけで決めず、自分で確かめる大切さを感じました。","model":"友人に勧められた町へ行きました。駅前は思ったほど静かではありませんでしたが、少し歩くと川沿いに落ち着いた道がありました。期待と違う点もありましたが、歩いてみたおかげで、自分の好きな場所を見つけられました。誰かの評価だけで決めず、自分で確かめる大切さを感じました。","audioText":"友人に勧められた町へ行きました。駅前は思ったほど静かではありませんでしたが、少し歩くと川沿いに落ち着いた道がありました。期待と違う点もありましたが、歩いてみたおかげで、自分の好きな場所を見つけられました。誰かの評価だけで決めず、自分で確かめる大切さを感じました。","note":"“川沿いに落ち着いた道” — Walking beyond the station lets the narrator form their own view.","source":"course.html#lesson-347"},"lesson:352:meaning":{"title":"About and toward: 〜について and 〜に対して","front":"What concern do nearby residents raise?","answer":"Noise at night.","context":"","promptAudio":"市は新しい自転車置き場の計画について、住民の意見を募集している。利用者に対しては便利になる一方、近くに住む人からは夜間の騒音を心配する声がある。計画の賛否だけを尋ねるのでは、こうした立場の違いが見えにくい。利用時間や照明の向きなど、具体的な条件ごとに意見を聞けば、調整できる点が分かるのではないか。","model":"市は新しい自転車置き場の計画について、住民の意見を募集している。利用者に対しては便利になる一方、近くに住む人からは夜間の騒音を心配する声がある。計画の賛否だけを尋ねるのでは、こうした立場の違いが見えにくい。利用時間や照明の向きなど、具体的な条件ごとに意見を聞けば、調整できる点が分かるのではないか。","audioText":"市は新しい自転車置き場の計画について、住民の意見を募集している。利用者に対しては便利になる一方、近くに住む人からは夜間の騒音を心配する声がある。計画の賛否だけを尋ねるのでは、こうした立場の違いが見えにくい。利用時間や照明の向きなど、具体的な条件ごとに意見を聞けば、調整できる点が分かるのではないか。","note":"“夜間の騒音” — Different stakeholders value convenience and quiet differently; this is not a complete rejection of the project.","source":"course.html#lesson-352"},"lesson:357:meaning":{"title":"By / depending on: 〜によって","front":"What distinction does the speaker emphasize?","answer":"Publishing information and making it reach the people who need it.","context":"","promptAudio":"同じ案内を出しても、伝わり方は利用者によって異なる。紙の掲示をよく読む人もいれば、音声の案内を頼りにする人もいる。担当者は「情報は公開した」と考えがちだが、公開することと必要な人に届くことは同じではない。媒体を増やすだけでなく、内容を確かめられる方法を用意することが重要だ。","model":"同じ案内を出しても、伝わり方は利用者によって異なる。紙の掲示をよく読む人もいれば、音声の案内を頼りにする人もいる。担当者は「情報は公開した」と考えがちだが、公開することと必要な人に届くことは同じではない。媒体を増やすだけでなく、内容を確かめられる方法を用意することが重要だ。","audioText":"同じ案内を出しても、伝わり方は利用者によって異なる。紙の掲示をよく読む人もいれば、音声の案内を頼りにする人もいる。担当者は「情報は公開した」と考えがちだが、公開することと必要な人に届くことは同じではない。媒体を増やすだけでなく、内容を確かめられる方法を用意することが重要だ。","note":"“公開することと必要な人に届くこと” — Availability alone does not establish that the message was received and understood.","source":"course.html#lesson-357"},"lesson:362:meaning":{"title":"As: 〜として","front":"What does the student do about matters beyond their expertise?","answer":"State what they know and check with the responsible person.","context":"","promptAudio":"地域の祭りに通訳として参加した学生は、言葉を訳すだけでは足りないと感じた。来場者が何を知りたいのかを確認し、出店者にも質問の背景を伝える必要があったからだ。専門家として断定できない内容については、分かる範囲を示し、担当者に確認した。役割を引き受けることは、何でも答えられるふりをすることではない。","model":"地域の祭りに通訳として参加した学生は、言葉を訳すだけでは足りないと感じた。来場者が何を知りたいのかを確認し、出店者にも質問の背景を伝える必要があったからだ。専門家として断定できない内容については、分かる範囲を示し、担当者に確認した。役割を引き受けることは、何でも答えられるふりをすることではない。","audioText":"地域の祭りに通訳として参加した学生は、言葉を訳すだけでは足りないと感じた。来場者が何を知りたいのかを確認し、出店者にも質問の背景を伝える必要があったからだ。専門家として断定できない内容については、分かる範囲を示し、担当者に確認した。役割を引き受けることは、何でも答えられるふりをすることではない。","note":"“分かる範囲を示し、担当者に確認” — The student's role includes acknowledging limits and confirming information.","source":"course.html#lesson-362"},"lesson:367:meaning":{"title":"In / at: 〜において","front":"Where will questions containing personal information be handled?","answer":"Through a separate contact route.","context":"","promptAudio":"オンライン説明会において、質問を受け付ける時間は最後の十分間だけだった。そのため、途中で疑問を持った参加者は、説明を聞きながら質問を覚えておかなければならなかった。主催者は次回から、質問を随時書き込める欄を設けるという。ただし、個人情報を含む質問は公開欄に書かず、別の窓口で受け付ける方針である。","model":"オンライン説明会において、質問を受け付ける時間は最後の十分間だけだった。そのため、途中で疑問を持った参加者は、説明を聞きながら質問を覚えておかなければならなかった。主催者は次回から、質問を随時書き込める欄を設けるという。ただし、個人情報を含む質問は公開欄に書かず、別の窓口で受け付ける方針である。","audioText":"オンライン説明会において、質問を受け付ける時間は最後の十分間だけだった。そのため、途中で疑問を持った参加者は、説明を聞きながら質問を覚えておかなければならなかった。主催者は次回から、質問を随時書き込める欄を設けるという。ただし、個人情報を含む質問は公開欄に書かず、別の窓口で受け付ける方針である。","note":"“別の窓口で受け付ける” — The new public field does not replace the separate route for private information.","source":"course.html#lesson-367"},"lesson:372:meaning":{"title":"Based on: 〜に基づいて","front":"Who makes up most of the survey respondents?","answer":"People who already use the library.","context":"","promptAudio":"利用者調査に基づいて、図書館は開館時間を変更した。夕方の利用を希望する声が多かったためだ。しかし、回答者の多くはすでに図書館を使っている人であり、利用していない人の事情までは分からない。調査結果は判断の手掛かりになるが、誰の声が含まれているかを確認しなければ、結論を広げすぎるおそれがある。","model":"利用者調査に基づいて、図書館は開館時間を変更した。夕方の利用を希望する声が多かったためだ。しかし、回答者の多くはすでに図書館を使っている人であり、利用していない人の事情までは分からない。調査結果は判断の手掛かりになるが、誰の声が含まれているかを確認しなければ、結論を広げすぎるおそれがある。","audioText":"利用者調査に基づいて、図書館は開館時間を変更した。夕方の利用を希望する声が多かったためだ。しかし、回答者の多くはすでに図書館を使っている人であり、利用していない人の事情までは分からない。調査結果は判断の手掛かりになるが、誰の声が含まれているかを確認しなければ、結論を広げすぎるおそれがある。","note":"“すでに図書館を使っている人” — The respondent group limits what can be inferred about non-users.","source":"course.html#lesson-372"},"lesson:377:meaning":{"title":"Around an issue: 〜をめぐって","front":"Which alternative use of the vacant land is proposed alongside a park?","answer":"A parking area.","context":"","promptAudio":"駅前の空き地をめぐって、公園にする案と駐車場にする案が議論されている。前者は休める場所の不足を、後者は周辺の交通事情を重視する。どちらも地域の課題に応えようとしており、相手の案を単に「不要だ」と片付けても話は進まない。判断するには、利用予測、維持費、代替施設の有無を同じ条件で比較する必要がある。","model":"駅前の空き地をめぐって、公園にする案と駐車場にする案が議論されている。前者は休める場所の不足を、後者は周辺の交通事情を重視する。どちらも地域の課題に応えようとしており、相手の案を単に「不要だ」と片付けても話は進まない。判断するには、利用予測、維持費、代替施設の有無を同じ条件で比較する必要がある。","audioText":"駅前の空き地をめぐって、公園にする案と駐車場にする案が議論されている。前者は休める場所の不足を、後者は周辺の交通事情を重視する。どちらも地域の課題に応えようとしており、相手の案を単に「不要だ」と片付けても話は進まない。判断するには、利用予測、維持費、代替施設の有無を同じ条件で比較する必要がある。","note":"“公園にする案と駐車場にする案” — The two proposals prioritize rest space and traffic-related needs.","source":"course.html#lesson-377"},"lesson:382:meaning":{"title":"Along with: 〜に伴って and 〜とともに","front":"What could keep a flexible-location job burdensome?","answer":"An expectation of being available to respond at all times.","context":"","promptAudio":"通信環境の変化に伴って、働く場所の選択肢が増えた。それとともに、連絡が取れる時間をどう定めるかという課題も生まれている。場所を自由に選べても、常に応答を求められるなら負担は減らない。制度を評価する際には、場所の柔軟さだけでなく、休む時間を確保できるかどうかにも目を向けるべきだ。","model":"通信環境の変化に伴って、働く場所の選択肢が増えた。それとともに、連絡が取れる時間をどう定めるかという課題も生まれている。場所を自由に選べても、常に応答を求められるなら負担は減らない。制度を評価する際には、場所の柔軟さだけでなく、休む時間を確保できるかどうかにも目を向けるべきだ。","audioText":"通信環境の変化に伴って、働く場所の選択肢が増えた。それとともに、連絡が取れる時間をどう定めるかという課題も生まれている。場所を自由に選べても、常に応答を求められるなら負担は減らない。制度を評価する際には、場所の柔軟さだけでなく、休む時間を確保できるかどうかにも目を向けるべきだ。","note":"“常に応答を求められる” — Freedom of location does not by itself guarantee protected rest time.","source":"course.html#lesson-382"},"lesson:387:meaning":{"title":"As soon as: 〜次第","front":"What will be reported every thirty minutes?","answer":"The progress of the safety check and the next update time.","context":"","promptAudio":"会場の安全確認が終わり次第、主催者は入場開始時刻を知らせる予定だ。参加者からは、目安だけでも先に知りたいという声が出ている。担当者は、確定していない時刻を断定することは避けたいとしている。そこで、確認の進み具合を三十分ごとに報告し、次に情報を更新する時刻を示すことにした。","model":"会場の安全確認が終わり次第、主催者は入場開始時刻を知らせる予定だ。参加者からは、目安だけでも先に知りたいという声が出ている。担当者は、確定していない時刻を断定することは避けたいとしている。そこで、確認の進み具合を三十分ごとに報告し、次に情報を更新する時刻を示すことにした。","audioText":"会場の安全確認が終わり次第、主催者は入場開始時刻を知らせる予定だ。参加者からは、目安だけでも先に知りたいという声が出ている。担当者は、確定していない時刻を断定することは避けたいとしている。そこで、確認の進み具合を三十分ごとに報告し、次に情報を更新する時刻を示すことにした。","note":"“確認の進み具合を三十分ごとに” — Progress reports offer useful information without inventing a confirmed opening time.","source":"course.html#lesson-387"},"lesson:392:meaning":{"title":"Although / even so: 〜ものの and 〜とはいえ","front":"Why consider retaining counter reservations despite their cost?","answer":"They may preserve access for people who struggle with the new method.","context":"","promptAudio":"新しい予約制度によって待ち時間は短くなったものの、予約方法が分からず困る人もいる。便利になったとはいえ、すべての利用者にとって使いやすいとは限らない。窓口での予約を残すと費用は増えるが、その費用を無駄と判断する前に、誰の利用機会を支えているのかを考える必要がある。","model":"新しい予約制度によって待ち時間は短くなったものの、予約方法が分からず困る人もいる。便利になったとはいえ、すべての利用者にとって使いやすいとは限らない。窓口での予約を残すと費用は増えるが、その費用を無駄と判断する前に、誰の利用機会を支えているのかを考える必要がある。","audioText":"新しい予約制度によって待ち時間は短くなったものの、予約方法が分からず困る人もいる。便利になったとはいえ、すべての利用者にとって使いやすいとは限らない。窓口での予約を残すと費用は増えるが、その費用を無駄と判断する前に、誰の利用機会を支えているのかを考える必要がある。","note":"“誰の利用機会を支えているのか” — The passage asks whose access the additional cost supports.","source":"course.html#lesson-392"},"lesson:397:meaning":{"title":"Workplace Japanese: the polite layer","front":"What is communicated after the internal check?","answer":"What is known, separated from what is still being checked.","context":"","promptAudio":"取引先から納期について問い合わせがあった。担当者は「確認いたします」と答え、社内の担当部署に状況を聞いた。その後、分かっている点と確認中の点を分けて伝えた。丁寧な表現を使うことは大切だが、曖昧な敬語だけで説明を終えてしまうと、相手は次に何をすればよいか判断できない。","model":"取引先から納期について問い合わせがあった。担当者は「確認いたします」と答え、社内の担当部署に状況を聞いた。その後、分かっている点と確認中の点を分けて伝えた。丁寧な表現を使うことは大切だが、曖昧な敬語だけで説明を終えてしまうと、相手は次に何をすればよいか判断できない。","audioText":"取引先から納期について問い合わせがあった。担当者は「確認いたします」と答え、社内の担当部署に状況を聞いた。その後、分かっている点と確認中の点を分けて伝えた。丁寧な表現を使うことは大切だが、曖昧な敬語だけで説明を終えてしまうと、相手は次に何をすればよいか判断できない。","note":"“分かっている点と確認中の点を分けて” — Useful business communication distinguishes confirmed information from pending checks.","source":"course.html#lesson-397"},"lesson:402:meaning":{"title":"No choice but: 〜ざるを得ない","front":"What does the speaker say should be examined separately from postponement?","answer":"The delay in notifying people travelling from far away.","context":"","promptAudio":"大雨で交通機関が止まったため、展示会の初日を延期せざるを得なくなった。主催者は中止を避けたかったが、安全を優先したという。問題は延期したことだけではない。遠方から来る予定だった人への連絡が遅れた点は、別に検証する必要がある。不可避な判断と、その伝え方に改善の余地があったことは両立する。","model":"大雨で交通機関が止まったため、展示会の初日を延期せざるを得なくなった。主催者は中止を避けたかったが、安全を優先したという。問題は延期したことだけではない。遠方から来る予定だった人への連絡が遅れた点は、別に検証する必要がある。不可避な判断と、その伝え方に改善の余地があったことは両立する。","audioText":"大雨で交通機関が止まったため、展示会の初日を延期せざるを得なくなった。主催者は中止を避けたかったが、安全を優先したという。問題は延期したことだけではない。遠方から来る予定だった人への連絡が遅れた点は、別に検証する必要がある。不可避な判断と、その伝え方に改善の余地があったことは両立する。","note":"“遠方から来る予定だった人への連絡が遅れた” — A constrained decision does not make every aspect of its communication unavoidable.","source":"course.html#lesson-402"},"lesson:407:meaning":{"title":"Might happen / cannot do","front":"What precaution is planned while more investigation is done?","answer":"Temporarily restrict use of the building.","context":"","promptAudio":"古い建物の調査で、一部の設備が故障しかねない状態だと分かった。管理者は詳しい結果が出るまで断定できないとしながらも、問題がないとは言いかねると説明した。危険が確定していないから何もしなくてよい、ということにはならない。利用を一時制限し、追加の調査を行う方針である。","model":"古い建物の調査で、一部の設備が故障しかねない状態だと分かった。管理者は詳しい結果が出るまで断定できないとしながらも、問題がないとは言いかねると説明した。危険が確定していないから何もしなくてよい、ということにはならない。利用を一時制限し、追加の調査を行う方針である。","audioText":"古い建物の調査で、一部の設備が故障しかねない状態だと分かった。管理者は詳しい結果が出るまで断定できないとしながらも、問題がないとは言いかねると説明した。危険が確定していないから何もしなくてよい、ということにはならない。利用を一時制限し、追加の調査を行う方針である。","note":"“利用を一時制限” — Uncertainty about the precise risk does not rule out a precaution.","source":"course.html#lesson-407"},"lesson:412:meaning":{"title":"Tendencies: 〜がち and 〜っぽい","front":"What tendency is mentioned for people working at home?","answer":"Forgetting breaks unless they pay attention.","context":"","promptAudio":"在宅勤務では、意識しないと休憩を忘れがちだ。一方、出勤する人にも、忙しい日は昼食を急いで済ませる傾向がある。働く場所だけで健康への影響を決めつけるのは早い。どんな条件で負担が増えるのかを調べ、行動の傾向を性格の問題に置き換えないことが大切だ。","model":"在宅勤務では、意識しないと休憩を忘れがちだ。一方、出勤する人にも、忙しい日は昼食を急いで済ませる傾向がある。働く場所だけで健康への影響を決めつけるのは早い。どんな条件で負担が増えるのかを調べ、行動の傾向を性格の問題に置き換えないことが大切だ。","audioText":"在宅勤務では、意識しないと休憩を忘れがちだ。一方、出勤する人にも、忙しい日は昼食を急いで済ませる傾向がある。働く場所だけで健康への影響を決めつけるのは早い。どんな条件で負担が増えるのかを調べ、行動の傾向を性格の問題に置き換えないことが大切だ。","note":"“休憩を忘れがち” — This is a tendency under certain conditions, not a universal personality judgment.","source":"course.html#lesson-412"},"lesson:417:meaning":{"title":"Looks and feelings: 〜げ and 〜がる","front":"What does the teacher do first in the feedback conversation?","answer":"Point to specific things the student communicated successfully.","context":"","promptAudio":"発表を終えた学生は不安げな表情をしていた。質問に答えた後も、「説明が足りなかったかもしれません」と話した。しかし、表情だけを見て発表が失敗したと判断することはできない。教員は、伝わった点を具体的に示したうえで、次回確かめたい点を一緒に整理した。","model":"発表を終えた学生は不安げな表情をしていた。質問に答えた後も、「説明が足りなかったかもしれません」と話した。しかし、表情だけを見て発表が失敗したと判断することはできない。教員は、伝わった点を具体的に示したうえで、次回確かめたい点を一緒に整理した。","audioText":"発表を終えた学生は不安げな表情をしていた。質問に答えた後も、「説明が足りなかったかもしれません」と話した。しかし、表情だけを見て発表が失敗したと判断することはできない。教員は、伝わった点を具体的に示したうえで、次回確かめたい点を一緒に整理した。","note":"“伝わった点を具体的に示したうえで” — The teacher starts with concrete evidence, then identifies points to examine next time.","source":"course.html#lesson-417"},"lesson:422:meaning":{"title":"In the middle of changing: 〜つつある","front":"Which support is described as insufficient?","answer":"Support after the short rental period ends.","context":"","promptAudio":"この商店街では、空き店舗を短期間だけ借りられる仕組みが広がりつつある。新しく店を始める人にとっては試しやすいが、利用期間が終わった後の支援は十分ではない。短期出店の件数が増えたことだけを成功の指標にすると、続けたい人が何に困っているかを見落とす可能性がある。","model":"この商店街では、空き店舗を短期間だけ借りられる仕組みが広がりつつある。新しく店を始める人にとっては試しやすいが、利用期間が終わった後の支援は十分ではない。短期出店の件数が増えたことだけを成功の指標にすると、続けたい人が何に困っているかを見落とす可能性がある。","audioText":"この商店街では、空き店舗を短期間だけ借りられる仕組みが広がりつつある。新しく店を始める人にとっては試しやすいが、利用期間が終わった後の支援は十分ではない。短期出店の件数が増えたことだけを成功の指標にすると、続けたい人が何に困っているかを見落とす可能性がある。","note":"“利用期間が終わった後の支援” — The trial scheme is spreading, but continuity after the trial remains an issue.","source":"course.html#lesson-422"},"lesson:427:meaning":{"title":"One direction only: 〜一方だ","front":"Why does searching for information still take time?","answer":"Duplicate documents make the current version hard to identify.","context":"","promptAudio":"資料の保存量は増える一方だが、必要な情報を探す時間まで短くなったとは言えない。同じ内容の文書が複数あり、どれが最新か分からないからだ。容量を追加するだけでは、この問題は解決しない。保存する量と、情報を使える状態に保つための仕組みを分けて考える必要がある。","model":"資料の保存量は増える一方だが、必要な情報を探す時間まで短くなったとは言えない。同じ内容の文書が複数あり、どれが最新か分からないからだ。容量を追加するだけでは、この問題は解決しない。保存する量と、情報を使える状態に保つための仕組みを分けて考える必要がある。","audioText":"資料の保存量は増える一方だが、必要な情報を探す時間まで短くなったとは言えない。同じ内容の文書が複数あり、どれが最新か分からないからだ。容量を追加するだけでは、この問題は解決しない。保存する量と、情報を使える状態に保つための仕組みを分けて考える必要がある。","note":"“どれが最新か分からない” — The problem is version reliability, rather than storage capacity alone.","source":"course.html#lesson-427"},"lesson:432:meaning":{"title":"Contrary to: 〜に反して","front":"What finding challenged the organizer's expectation?","answer":"Many young people attended the new morning class.","context":"","promptAudio":"予想に反して、新しい朝の講座には若い参加者も多かった。担当者は、平日の昼間に参加できる人は限られるという前提を見直した。ただし、一度の結果だけで、すべての講座を朝に移すことはできない。参加理由を尋ね、別の時期にも同じ傾向が見られるか確かめる予定だ。","model":"予想に反して、新しい朝の講座には若い参加者も多かった。担当者は、平日の昼間に参加できる人は限られるという前提を見直した。ただし、一度の結果だけで、すべての講座を朝に移すことはできない。参加理由を尋ね、別の時期にも同じ傾向が見られるか確かめる予定だ。","audioText":"予想に反して、新しい朝の講座には若い参加者も多かった。担当者は、平日の昼間に参加できる人は限られるという前提を見直した。ただし、一度の結果だけで、すべての講座を朝に移すことはできない。参加理由を尋ね、別の時期にも同じ傾向が見られるか確かめる予定だ。","note":"“若い参加者も多かった” — The result motivates further inquiry; it does not justify an immediate change to every course.","source":"course.html#lesson-432"},"lesson:437:meaning":{"title":"Not only: 〜だけでなく and 〜に限らず","front":"Which practical learning purpose is mentioned besides exams?","answer":"Reading notices from a school.","context":"","promptAudio":"地域の日本語教室には、学生だけでなく、働く人や子育て中の人も通っている。学習目的も試験に限らず、学校からの連絡を読むことや近所の人と話すことなどさまざまだ。教材を一つに統一すれば運営は簡単になるが、共通の練習と個別の目的を両立させる工夫が必要になる。","model":"地域の日本語教室には、学生だけでなく、働く人や子育て中の人も通っている。学習目的も試験に限らず、学校からの連絡を読むことや近所の人と話すことなどさまざまだ。教材を一つに統一すれば運営は簡単になるが、共通の練習と個別の目的を両立させる工夫が必要になる。","audioText":"地域の日本語教室には、学生だけでなく、働く人や子育て中の人も通っている。学習目的も試験に限らず、学校からの連絡を読むことや近所の人と話すことなどさまざまだ。教材を一つに統一すれば運営は簡単になるが、共通の練習と個別の目的を両立させる工夫が必要になる。","note":"“学校からの連絡を読む” — The classroom serves varied everyday purposes in addition to tests.","source":"course.html#lesson-437"},"lesson:442:meaning":{"title":"Regardless of: 〜を問わず","front":"What support is added beyond broadening eligibility?","answer":"An approachable question desk and a short explanation.","context":"","promptAudio":"この企画は経験の有無を問わず参加できる。ただし、初心者も参加できると書くだけでは、実際に取り組めるとは限らない。使う道具や作業の手順が分からなければ、不安に感じるだろう。参加資格を広げることに加え、質問しやすい窓口と短い説明を用意することにした。","model":"この企画は経験の有無を問わず参加できる。ただし、初心者も参加できると書くだけでは、実際に取り組めるとは限らない。使う道具や作業の手順が分からなければ、不安に感じるだろう。参加資格を広げることに加え、質問しやすい窓口と短い説明を用意することにした。","audioText":"この企画は経験の有無を問わず参加できる。ただし、初心者も参加できると書くだけでは、実際に取り組めるとは限らない。使う道具や作業の手順が分からなければ、不安に感じるだろう。参加資格を広げることに加え、質問しやすい窓口と短い説明を用意することにした。","note":"“質問しやすい窓口と短い説明” — Open eligibility needs practical support to become usable access.","source":"course.html#lesson-442"},"lesson:447:meaning":{"title":"Read between the lines","front":"What change would allow the colleague to attend?","answer":"Starting later.","context":"","promptAudio":"会議で新しい日程案が出たとき、ある同僚は「その日は少し難しいかもしれません」と言った。司会者は反対と決めつけず、何が難しいのかを尋ねた。すると、開始時刻を遅らせれば参加できると分かった。控えめな表現を理解するには、隠れた意味を一つに決めるのではなく、確かめるやり取りが役に立つ。","model":"会議で新しい日程案が出たとき、ある同僚は「その日は少し難しいかもしれません」と言った。司会者は反対と決めつけず、何が難しいのかを尋ねた。すると、開始時刻を遅らせれば参加できると分かった。控えめな表現を理解するには、隠れた意味を一つに決めるのではなく、確かめるやり取りが役に立つ。","audioText":"会議で新しい日程案が出たとき、ある同僚は「その日は少し難しいかもしれません」と言った。司会者は反対と決めつけず、何が難しいのかを尋ねた。すると、開始時刻を遅らせれば参加できると分かった。控えめな表現を理解するには、隠れた意味を一つに決めるのではなく、確かめるやり取りが役に立つ。","note":"“開始時刻を遅らせれば参加できる” — Clarification reveals a specific time issue rather than an unconditional refusal.","source":"course.html#lesson-447"},"lesson:452:meaning":{"title":"Starting with: 〜を皮切りに","front":"What led organizers to pay more attention to post-screening discussion?","answer":"More audience members connected the film with their own experiences.","context":"","promptAudio":"地方の小さな映画館での上映を皮切りに、監督は各地で作品について語る会を開いた。当初、主催者は参加者の数を重視していたが、会を重ねるうちに、上映後の対話にも注目するようになった。観客が自分の経験に結び付けて話す場面が増えたからである。開催地が増えたことは活動の広がりを示すが、それだけでは作品がどう受け止められたかは分からない。規模と内容を別々に記録する必要があるだろう。","model":"地方の小さな映画館での上映を皮切りに、監督は各地で作品について語る会を開いた。当初、主催者は参加者の数を重視していたが、会を重ねるうちに、上映後の対話にも注目するようになった。観客が自分の経験に結び付けて話す場面が増えたからである。開催地が増えたことは活動の広がりを示すが、それだけでは作品がどう受け止められたかは分からない。規模と内容を別々に記録する必要があるだろう。","audioText":"地方の小さな映画館での上映を皮切りに、監督は各地で作品について語る会を開いた。当初、主催者は参加者の数を重視していたが、会を重ねるうちに、上映後の対話にも注目するようになった。観客が自分の経験に結び付けて話す場面が増えたからである。開催地が増えたことは活動の広がりを示すが、それだけでは作品がどう受け止められたかは分からない。規模と内容を別々に記録する必要があるだろう。","note":"“自分の経験に結び付けて話す場面が増えた” — This is evidence about engagement, distinct from the activity's geographic scale.","source":"course.html#lesson-452"},"lesson:457:meaning":{"title":"Cannot help doing: 〜ずにはいられない","front":"What does the narrator recognize while rereading old letters?","answer":"A friend's thoughtfulness that they had not understood at the time.","context":"","promptAudio":"引っ越しの荷物を整理していると、学生時代の手紙が出てきた。読み返すうちに、当時は理解できなかった友人の気遣いに気付かずにはいられなかった。過去の出来事が変わったわけではない。それでも、自分の経験が増えることで、同じ言葉の受け取り方は変わる。懐かしさだけを語るなら簡単だが、その変化を説明しようとすると、かつての自分の狭さにも向き合わなければならない。","model":"引っ越しの荷物を整理していると、学生時代の手紙が出てきた。読み返すうちに、当時は理解できなかった友人の気遣いに気付かずにはいられなかった。過去の出来事が変わったわけではない。それでも、自分の経験が増えることで、同じ言葉の受け取り方は変わる。懐かしさだけを語るなら簡単だが、その変化を説明しようとすると、かつての自分の狭さにも向き合わなければならない。","audioText":"引っ越しの荷物を整理していると、学生時代の手紙が出てきた。読み返すうちに、当時は理解できなかった友人の気遣いに気付かずにはいられなかった。過去の出来事が変わったわけではない。それでも、自分の経験が増えることで、同じ言葉の受け取り方は変わる。懐かしさだけを語るなら簡単だが、その変化を説明しようとすると、かつての自分の狭さにも向き合わなければならない。","note":"“当時は理解できなかった友人の気遣い” — Later experience changes the narrator's interpretation of the unchanged words.","source":"course.html#lesson-457"},"lesson:462:meaning":{"title":"Either… or: 〜なり〜なり","front":"Which contact method is suggested as suitable when urgency matters?","answer":"Telephone.","context":"","promptAudio":"相談を受けた側は、電話なりメールなりで連絡してほしいと伝えた。選択肢を示したつもりだったが、相手はどの方法を選ぶべきか迷ってしまった。急ぐ場合は電話、資料を添える場合はメールという説明があれば、判断しやすかっただろう。選択の自由は、選ぶための情報があってこそ役に立つ。方法を列挙することと、相手が決められるようにすることは、必ずしも同じではない。","model":"相談を受けた側は、電話なりメールなりで連絡してほしいと伝えた。選択肢を示したつもりだったが、相手はどの方法を選ぶべきか迷ってしまった。急ぐ場合は電話、資料を添える場合はメールという説明があれば、判断しやすかっただろう。選択の自由は、選ぶための情報があってこそ役に立つ。方法を列挙することと、相手が決められるようにすることは、必ずしも同じではない。","audioText":"相談を受けた側は、電話なりメールなりで連絡してほしいと伝えた。選択肢を示したつもりだったが、相手はどの方法を選ぶべきか迷ってしまった。急ぐ場合は電話、資料を添える場合はメールという説明があれば、判断しやすかっただろう。選択の自由は、選ぶための情報があってこそ役に立つ。方法を列挙することと、相手が決められるようにすることは、必ずしも同じではない。","note":"“急ぐ場合は電話” — The retrospective explanation pairs urgent cases with telephone and attachments with email.","source":"course.html#lesson-462"},"lesson:467:meaning":{"title":"As soon as: 〜が早いか","front":"What does the passage establish about the applause?","answer":"It began almost immediately after the curtain rose.","context":"","promptAudio":"幕が上がるが早いか、客席から大きな拍手が起こった。記事はその瞬間を生き生きと描いている。しかし、その一文だけでは、なぜ観客が拍手したのかは分からない。長く待ち望まれた再演だったのか、舞台の装置に驚いたのか、別の事情があったのか。出来事の速さを強調する表現は、原因の説明まで含むわけではない。描写から受けた印象と、文章が実際に示している情報を区別したい。","model":"幕が上がるが早いか、客席から大きな拍手が起こった。記事はその瞬間を生き生きと描いている。しかし、その一文だけでは、なぜ観客が拍手したのかは分からない。長く待ち望まれた再演だったのか、舞台の装置に驚いたのか、別の事情があったのか。出来事の速さを強調する表現は、原因の説明まで含むわけではない。描写から受けた印象と、文章が実際に示している情報を区別したい。","audioText":"幕が上がるが早いか、客席から大きな拍手が起こった。記事はその瞬間を生き生きと描いている。しかし、その一文だけでは、なぜ観客が拍手したのかは分からない。長く待ち望まれた再演だったのか、舞台の装置に驚いたのか、別の事情があったのか。出来事の速さを強調する表現は、原因の説明まで含むわけではない。描写から受けた印象と、文章が実際に示している情報を区別したい。","note":"“幕が上がるが早いか” — The expression conveys timing vividly; the cause is deliberately left open.","source":"course.html#lesson-467"},"lesson:472:meaning":{"title":"The moment: 〜や否や","front":"Why did many of the inquiries concern basic conditions?","answer":"The announcement had not conveyed those conditions clearly to some people.","context":"","promptAudio":"新制度の発表が終わるや否や、窓口には多くの問い合わせが寄せられた。担当部署は反響の大きさを歓迎したが、問い合わせの内容を分析すると、基本的な条件が伝わっていない例も少なくなかった。反応が早く多かったことを、理解や支持の広がりと同一視することはできない。注目を集める発表と、行動に必要な情報を届ける説明には、異なる工夫が求められる。","model":"新制度の発表が終わるや否や、窓口には多くの問い合わせが寄せられた。担当部署は反響の大きさを歓迎したが、問い合わせの内容を分析すると、基本的な条件が伝わっていない例も少なくなかった。反応が早く多かったことを、理解や支持の広がりと同一視することはできない。注目を集める発表と、行動に必要な情報を届ける説明には、異なる工夫が求められる。","audioText":"新制度の発表が終わるや否や、窓口には多くの問い合わせが寄せられた。担当部署は反響の大きさを歓迎したが、問い合わせの内容を分析すると、基本的な条件が伝わっていない例も少なくなかった。反応が早く多かったことを、理解や支持の広がりと同一視することはできない。注目を集める発表と、行動に必要な情報を届ける説明には、異なる工夫が求められる。","note":"“基本的な条件が伝わっていない” — High and rapid response counts can include confusion rather than understanding or support.","source":"course.html#lesson-472"},"lesson:477:meaning":{"title":"When it comes to: 〜ともなると","front":"Which action can be part of a responsible role?","answer":"Consulting people with different expertise and sharing reasons.","context":"","promptAudio":"担当者ともなると、自分の作業だけでなく、チーム全体の進み具合にも目を向ける必要がある。ただ、経験が豊富だからといって、すべての判断を一人で引き受けるべきだとは限らない。専門の異なる人に相談し、判断の根拠を共有することも役割の一部である。責任の重さを強調しすぎると、助けを求めることを弱さだと感じさせかねない。立場に伴う期待を述べる際には、その期待を支える条件も示したい。","model":"担当者ともなると、自分の作業だけでなく、チーム全体の進み具合にも目を向ける必要がある。ただ、経験が豊富だからといって、すべての判断を一人で引き受けるべきだとは限らない。専門の異なる人に相談し、判断の根拠を共有することも役割の一部である。責任の重さを強調しすぎると、助けを求めることを弱さだと感じさせかねない。立場に伴う期待を述べる際には、その期待を支える条件も示したい。","audioText":"担当者ともなると、自分の作業だけでなく、チーム全体の進み具合にも目を向ける必要がある。ただ、経験が豊富だからといって、すべての判断を一人で引き受けるべきだとは限らない。専門の異なる人に相談し、判断の根拠を共有することも役割の一部である。責任の重さを強調しすぎると、助けを求めることを弱さだと感じさせかねない。立場に伴う期待を述べる際には、その期待を支える条件も示したい。","note":"“専門の異なる人に相談し、判断の根拠を共有” — Responsibility includes using support and explaining grounds for decisions.","source":"course.html#lesson-477"},"lesson:482:meaning":{"title":"Therefore / because: 〜ゆえに","front":"What comparison does the speaker recommend?","answer":"Who benefits and who bears burdens under each arrangement.","context":"","promptAudio":"長年続いてきた制度ゆえに、その手続きを変えることには抵抗もある。しかし、長く続いたという事実だけで、現在も最適だと判断することはできない。一方、新しいという理由だけで別の制度を優れているとみなすことも早計である。比較すべきなのは名称や年数ではなく、誰にどのような利益と負担が生じるかだ。変更の議論には、継続の価値と見直しの必要性を同じ土台で扱う姿勢が求められる。","model":"長年続いてきた制度ゆえに、その手続きを変えることには抵抗もある。しかし、長く続いたという事実だけで、現在も最適だと判断することはできない。一方、新しいという理由だけで別の制度を優れているとみなすことも早計である。比較すべきなのは名称や年数ではなく、誰にどのような利益と負担が生じるかだ。変更の議論には、継続の価値と見直しの必要性を同じ土台で扱う姿勢が求められる。","audioText":"長年続いてきた制度ゆえに、その手続きを変えることには抵抗もある。しかし、長く続いたという事実だけで、現在も最適だと判断することはできない。一方、新しいという理由だけで別の制度を優れているとみなすことも早計である。比較すべきなのは名称や年数ではなく、誰にどのような利益と負担が生じるかだ。変更の議論には、継続の価値と見直しの必要性を同じ土台で扱う姿勢が求められる。","note":"“誰にどのような利益と負担” — Neither longevity nor novelty alone establishes suitability.","source":"course.html#lesson-482"},"lesson:487:meaning":{"title":"As if about to: 〜んばかりに","front":"What action was NOT actually observed?","answer":"The speaker striking the desk.","context":"","promptAudio":"発言者は机をたたかんばかりの勢いで説明したが、実際に机をたたいたわけではなかった。記録者が比喩をそのまま行為の記述に置き換えれば、読み手は出来事を誤って理解する可能性がある。勢いの強さを伝えるには効果的な表現でも、議事録では別の書き方が適切だろう。文章の目的が変われば、残すべき情報と表現の仕方も変わる。臨場感を保つことと、確認できる事実を記すことを意識して使い分けたい。","model":"発言者は机をたたかんばかりの勢いで説明したが、実際に机をたたいたわけではなかった。記録者が比喩をそのまま行為の記述に置き換えれば、読み手は出来事を誤って理解する可能性がある。勢いの強さを伝えるには効果的な表現でも、議事録では別の書き方が適切だろう。文章の目的が変われば、残すべき情報と表現の仕方も変わる。臨場感を保つことと、確認できる事実を記すことを意識して使い分けたい。","audioText":"発言者は机をたたかんばかりの勢いで説明したが、実際に机をたたいたわけではなかった。記録者が比喩をそのまま行為の記述に置き換えれば、読み手は出来事を誤って理解する可能性がある。勢いの強さを伝えるには効果的な表現でも、議事録では別の書き方が適切だろう。文章の目的が変われば、残すべき情報と表現の仕方も変わる。臨場感を保つことと、確認できる事実を記すことを意識して使い分けたい。","note":"“実際に机をたたいたわけではなかった” — んばかりに conveys an impression close to an action, not proof that it occurred.","source":"course.html#lesson-487"},"lesson:492:meaning":{"title":"Unbecoming: 〜まじき","front":"What should a strong criticism make explicit?","answer":"The specific utterance and the role-based expectation it violated.","context":"","promptAudio":"責任ある立場にあるまじき発言だ、という批判が出た。この表現は強い非難を含むため、使う側にも根拠を示す責任がある。相手の人格全体を否定するのではなく、どの発言が、どの役割上の期待に反したのかを明確にする必要があるだろう。強い言葉を選べば議論が深まるとは限らない。批判の対象と基準が共有されて初めて、改善について具体的に話し合える。","model":"責任ある立場にあるまじき発言だ、という批判が出た。この表現は強い非難を含むため、使う側にも根拠を示す責任がある。相手の人格全体を否定するのではなく、どの発言が、どの役割上の期待に反したのかを明確にする必要があるだろう。強い言葉を選べば議論が深まるとは限らない。批判の対象と基準が共有されて初めて、改善について具体的に話し合える。","audioText":"責任ある立場にあるまじき発言だ、という批判が出た。この表現は強い非難を含むため、使う側にも根拠を示す責任がある。相手の人格全体を否定するのではなく、どの発言が、どの役割上の期待に反したのかを明確にする必要があるだろう。強い言葉を選べば議論が深まるとは限らない。批判の対象と基準が共有されて初めて、改善について具体的に話し合える。","note":"“どの発言が、どの役割上の期待に反した” — The criticism needs a specified target and shared standard.","source":"course.html#lesson-492"},"lesson:497:meaning":{"title":"The long conversation","front":"What should be separated at the end of a discussion?","answer":"Points of agreement and problems that remain.","context":"","promptAudio":"話し合いの目的は、相手を言い負かすことだけではない。意見が違っていても、どの事実を重視し、どの条件なら判断を変えるのかを確かめれば、対立の輪郭ははっきりする。分からない点を言い換えて尋ねることは、理解力の不足を示すのではなく、議論を正確に進めるための行動だ。最後に一致した点と残った問題を分けて整理すれば、結論が出なかった会話にも次の一歩が生まれる。","model":"話し合いの目的は、相手を言い負かすことだけではない。意見が違っていても、どの事実を重視し、どの条件なら判断を変えるのかを確かめれば、対立の輪郭ははっきりする。分からない点を言い換えて尋ねることは、理解力の不足を示すのではなく、議論を正確に進めるための行動だ。最後に一致した点と残った問題を分けて整理すれば、結論が出なかった会話にも次の一歩が生まれる。","audioText":"話し合いの目的は、相手を言い負かすことだけではない。意見が違っていても、どの事実を重視し、どの条件なら判断を変えるのかを確かめれば、対立の輪郭ははっきりする。分からない点を言い換えて尋ねることは、理解力の不足を示すのではなく、議論を正確に進めるための行動だ。最後に一致した点と残った問題を分けて整理すれば、結論が出なかった会話にも次の一歩が生まれる。","note":"“一致した点と残った問題” — This separation gives an unresolved conversation a useful next step.","source":"course.html#lesson-497"},"lesson:502:meaning":{"title":"Trace the full scope of a proposal","front":"Whose experience might a detailed plan still overlook?","answer":"People whose needs were not anticipated in the plan.","context":"","promptAudio":"新しい交流施設の計画書は、受付から退館時の案内に至るまで、利用者の動きを細かく示している。図面だけでは見えにくい場面を想像できる点は有益だ。一方、記述が詳しいからといって、想定されていない利用者がいないとは限らない。例えば、説明を聞き取りにくい人や、予定を変更せざるを得ない人への対応はどうだろうか。計画を評価する際には、書かれている範囲の広さだけでなく、誰の経験が前提になっているかも確かめたい。網羅性は重要な観点だが、それを十分性と同一視しない読み方が必要である。","model":"新しい交流施設の計画書は、受付から退館時の案内に至るまで、利用者の動きを細かく示している。図面だけでは見えにくい場面を想像できる点は有益だ。一方、記述が詳しいからといって、想定されていない利用者がいないとは限らない。例えば、説明を聞き取りにくい人や、予定を変更せざるを得ない人への対応はどうだろうか。計画を評価する際には、書かれている範囲の広さだけでなく、誰の経験が前提になっているかも確かめたい。網羅性は重要な観点だが、それを十分性と同一視しない読み方が必要である。","audioText":"新しい交流施設の計画書は、受付から退館時の案内に至るまで、利用者の動きを細かく示している。図面だけでは見えにくい場面を想像できる点は有益だ。一方、記述が詳しいからといって、想定されていない利用者がいないとは限らない。例えば、説明を聞き取りにくい人や、予定を変更せざるを得ない人への対応はどうだろうか。計画を評価する際には、書かれている範囲の広さだけでなく、誰の経験が前提になっているかも確かめたい。網羅性は重要な観点だが、それを十分性と同一視しない読み方が必要である。","note":"“想定されていない利用者” — Detail within an assumed scope does not establish sufficiency for every user.","source":"course.html#lesson-502"},"lesson:507:meaning":{"title":"Explain an unavoidable change responsibly","front":"What information did participants need in addition to the reason for the venue change?","answer":"Directions, extra costs, and a contact for withdrawing.","context":"","promptAudio":"地域の展示企画は、建物の不具合によって会場変更を余儀なくされた。運営側は、急な出来事だったことを繰り返し説明したが、参加者が求めていたのは事情の説明だけではなかった。新会場への行き方、追加の費用、参加を取りやめる場合の連絡先も必要だったのである。変更そのものを避けられなかったとしても、影響を受ける人が判断できる情報を整える余地はあった。責任を論じる際には、出来事の発生、変更の判断、その後の対応を分けて考えるべきだろう。すべてを不可抗力として一括りにすれば、改善可能な部分まで見えなくなる。","model":"地域の展示企画は、建物の不具合によって会場変更を余儀なくされた。運営側は、急な出来事だったことを繰り返し説明したが、参加者が求めていたのは事情の説明だけではなかった。新会場への行き方、追加の費用、参加を取りやめる場合の連絡先も必要だったのである。変更そのものを避けられなかったとしても、影響を受ける人が判断できる情報を整える余地はあった。責任を論じる際には、出来事の発生、変更の判断、その後の対応を分けて考えるべきだろう。すべてを不可抗力として一括りにすれば、改善可能な部分まで見えなくなる。","audioText":"地域の展示企画は、建物の不具合によって会場変更を余儀なくされた。運営側は、急な出来事だったことを繰り返し説明したが、参加者が求めていたのは事情の説明だけではなかった。新会場への行き方、追加の費用、参加を取りやめる場合の連絡先も必要だったのである。変更そのものを避けられなかったとしても、影響を受ける人が判断できる情報を整える余地はあった。責任を論じる際には、出来事の発生、変更の判断、その後の対応を分けて考えるべきだろう。すべてを不可抗力として一括りにすれば、改善可能な部分まで見えなくなる。","note":"“新会場への行き方、追加の費用” — Useful decisions require concrete consequences and available actions, not only an explanation of cause.","source":"course.html#lesson-507"},"lesson:512:meaning":{"title":"Make a proportionate concession","front":"What minimum provision does the speaker identify?","answer":"A way to seek help when difficulties arise.","context":"","promptAudio":"すべての利用者が満足しないまでも、困ったときに相談できる仕組みは必要だ。ところが、「全員を満足させることはできない」という当然の限界が、改善を見送る理由として使われることがある。完全な解決が難しいことと、負担を減らす方法がないことは別である。まず、どの困難がどれだけ軽くなるのかを示し、残る問題も明らかにしたい。目標を現実的にすることは、最初から期待を下げて終わることではない。達成できる範囲を具体的にし、その範囲でも意味のある変化を目指す姿勢が求められる。","model":"すべての利用者が満足しないまでも、困ったときに相談できる仕組みは必要だ。ところが、「全員を満足させることはできない」という当然の限界が、改善を見送る理由として使われることがある。完全な解決が難しいことと、負担を減らす方法がないことは別である。まず、どの困難がどれだけ軽くなるのかを示し、残る問題も明らかにしたい。目標を現実的にすることは、最初から期待を下げて終わることではない。達成できる範囲を具体的にし、その範囲でも意味のある変化を目指す姿勢が求められる。","audioText":"すべての利用者が満足しないまでも、困ったときに相談できる仕組みは必要だ。ところが、「全員を満足させることはできない」という当然の限界が、改善を見送る理由として使われることがある。完全な解決が難しいことと、負担を減らす方法がないことは別である。まず、どの困難がどれだけ軽くなるのかを示し、残る問題も明らかにしたい。目標を現実的にすることは、最初から期待を下げて終わることではない。達成できる範囲を具体的にし、その範囲でも意味のある変化を目指す姿勢が求められる。","note":"“困ったときに相談できる仕組み” — A realistic minimum can matter even when universal satisfaction is unattainable.","source":"course.html#lesson-512"},"lesson:517:meaning":{"title":"Test a strongly worded conclusion","front":"What changed besides the publicity method?","answer":"Transport access improved and more event days were offered.","context":"","promptAudio":"広報担当者は、参加者の増加は宣伝方法を変えた成果にほかならないと述べた。確かに、変更後に参加者は増えている。しかし、同じ時期に会場への交通も便利になり、開催日も増えていた。時間的に前後しているという事実だけでは、どの要因がどれほど影響したかは判断できない。宣伝の効果を否定する必要はないが、他の説明を検討せずに原因を一つに絞るのも適切ではない。強い断定は文章を分かりやすく見せる一方で、まだ確かめられていない部分を隠してしまうことがある。","model":"広報担当者は、参加者の増加は宣伝方法を変えた成果にほかならないと述べた。確かに、変更後に参加者は増えている。しかし、同じ時期に会場への交通も便利になり、開催日も増えていた。時間的に前後しているという事実だけでは、どの要因がどれほど影響したかは判断できない。宣伝の効果を否定する必要はないが、他の説明を検討せずに原因を一つに絞るのも適切ではない。強い断定は文章を分かりやすく見せる一方で、まだ確かめられていない部分を隠してしまうことがある。","audioText":"広報担当者は、参加者の増加は宣伝方法を変えた成果にほかならないと述べた。確かに、変更後に参加者は増えている。しかし、同じ時期に会場への交通も便利になり、開催日も増えていた。時間的に前後しているという事実だけでは、どの要因がどれほど影響したかは判断できない。宣伝の効果を否定する必要はないが、他の説明を検討せずに原因を一つに絞るのも適切ではない。強い断定は文章を分かりやすく見せる一方で、まだ確かめられていない部分を隠してしまうことがある。","note":"“会場への交通も便利になり、開催日も増えて” — Other contemporaneous changes are plausible alternative explanations of the increase.","source":"course.html#lesson-517"},"lesson:522:meaning":{"title":"Read conditions and exceptions precisely","front":"What can prevent an application from being accepted for assessment?","answer":"Missing required documents.","context":"","promptAudio":"架空の募集案内には「審査の結果のいかんにかかわらず、全員に通知します」とある。これは、不合格でも通知を受け取れるという意味であり、審査が不要だという意味ではない。別の欄には、必要書類がそろっていない場合は受け付けないと書かれている。読み手が一文だけを切り取れば、申し込んだ人は誰でも審査されると誤解するかもしれない。条件文を読む際には、何にかかわらないのか、どの段階の手続きなのか、ほかの条件が残るのかを整理する必要がある。この例は語彙だけでなく、文書全体の構造を読む練習になる。","model":"架空の募集案内には「審査の結果のいかんにかかわらず、全員に通知します」とある。これは、不合格でも通知を受け取れるという意味であり、審査が不要だという意味ではない。別の欄には、必要書類がそろっていない場合は受け付けないと書かれている。読み手が一文だけを切り取れば、申し込んだ人は誰でも審査されると誤解するかもしれない。条件文を読む際には、何にかかわらないのか、どの段階の手続きなのか、ほかの条件が残るのかを整理する必要がある。この例は語彙だけでなく、文書全体の構造を読む練習になる。","audioText":"架空の募集案内には「審査の結果のいかんにかかわらず、全員に通知します」とある。これは、不合格でも通知を受け取れるという意味であり、審査が不要だという意味ではない。別の欄には、必要書類がそろっていない場合は受け付けないと書かれている。読み手が一文だけを切り取れば、申し込んだ人は誰でも審査されると誤解するかもしれない。条件文を読む際には、何にかかわらないのか、どの段階の手続きなのか、ほかの条件が残るのかを整理する必要がある。この例は語彙だけでなく、文書全体の構造を読む練習になる。","note":"“必要書類がそろっていない場合は受け付けない” — The acceptance condition remains separate from notification regardless of the assessment outcome.","source":"course.html#lesson-522"},"lesson:527:meaning":{"title":"Challenge an appeal to expertise","front":"How should a changed expert view be examined?","answer":"Distinguish revision based on new information from problems in the earlier explanation.","context":"","promptAudio":"専門家といえども、限られた資料からすべての結果を予測することはできない。だからといって、専門的な判断と根拠のない推測を同じように扱ってよいわけでもない。重要なのは、誰が話したかだけではなく、どの資料を使い、どの条件を仮定し、どこに不確実さが残るかを確かめることである。見解が後で変わった場合にも、新しい情報による修正なのか、最初の説明に問題があったのかを分けて考えたい。権威への無条件の服従と、専門性への全面的な不信の間には、根拠を吟味しながら判断する道がある。","model":"専門家といえども、限られた資料からすべての結果を予測することはできない。だからといって、専門的な判断と根拠のない推測を同じように扱ってよいわけでもない。重要なのは、誰が話したかだけではなく、どの資料を使い、どの条件を仮定し、どこに不確実さが残るかを確かめることである。見解が後で変わった場合にも、新しい情報による修正なのか、最初の説明に問題があったのかを分けて考えたい。権威への無条件の服従と、専門性への全面的な不信の間には、根拠を吟味しながら判断する道がある。","audioText":"専門家といえども、限られた資料からすべての結果を予測することはできない。だからといって、専門的な判断と根拠のない推測を同じように扱ってよいわけでもない。重要なのは、誰が話したかだけではなく、どの資料を使い、どの条件を仮定し、どこに不確実さが残るかを確かめることである。見解が後で変わった場合にも、新しい情報による修正なのか、最初の説明に問題があったのかを分けて考えたい。権威への無条件の服従と、専門性への全面的な不信の間には、根拠を吟味しながら判断する道がある。","note":"“新しい情報による修正なのか” — The passage argues for examining grounds and uncertainty rather than unconditional trust or distrust.","source":"course.html#lesson-527"},"lesson:532:meaning":{"title":"Announce a transition with precision","front":"What transition detail was missing from the announcement?","answer":"How ongoing cases would be handed over.","context":"","promptAudio":"架空の相談センターは、今月末をもって旧窓口の受付を終了すると発表した。しかし、新窓口がいつから利用できるのか、すでに相談中の案件はどこが引き継ぐのかが示されていなかった。終了時点だけを明確にしても、利用者が次に取る行動は分からない。移行の案内には、旧制度の終わり、新制度の始まり、途中の案件の扱い、困った場合の問い合わせ先が必要だろう。簡潔な告知は読みやすいが、必要な区別まで省けば、短さがかえって利用者の負担を増やすことになる。","model":"架空の相談センターは、今月末をもって旧窓口の受付を終了すると発表した。しかし、新窓口がいつから利用できるのか、すでに相談中の案件はどこが引き継ぐのかが示されていなかった。終了時点だけを明確にしても、利用者が次に取る行動は分からない。移行の案内には、旧制度の終わり、新制度の始まり、途中の案件の扱い、困った場合の問い合わせ先が必要だろう。簡潔な告知は読みやすいが、必要な区別まで省けば、短さがかえって利用者の負担を増やすことになる。","audioText":"架空の相談センターは、今月末をもって旧窓口の受付を終了すると発表した。しかし、新窓口がいつから利用できるのか、すでに相談中の案件はどこが引き継ぐのかが示されていなかった。終了時点だけを明確にしても、利用者が次に取る行動は分からない。移行の案内には、旧制度の終わり、新制度の始まり、途中の案件の扱い、困った場合の問い合わせ先が必要だろう。簡潔な告知は読みやすいが、必要な区別まで省けば、短さがかえって利用者の負担を増やすことになる。","note":"“相談中の案件はどこが引き継ぐ” — The old end date is explicit; continuity for current users is not.","source":"course.html#lesson-532"},"lesson:537:meaning":{"title":"Adapt a rule to actual circumstances","front":"Why is training content adjusted to local circumstances?","answer":"So participants with different experience can reach the shared goal.","context":"","promptAudio":"ある団体は、全国で同じ研修を実施していたが、現場の状況に即して内容を調整することにした。共通の基準をなくすためではなく、経験の異なる参加者が同じ目標に到達できるようにするためだ。ただし、現場に合わせるという説明だけでは、どこまで変更してよいかが曖昧になる。守るべき目的と、変えてよい方法を分けて示す必要があるだろう。原則と実情を対立させるのではなく、変更した方法が原則をどう支えるのかを説明できてこそ、調整の妥当性を検討できる。","model":"ある団体は、全国で同じ研修を実施していたが、現場の状況に即して内容を調整することにした。共通の基準をなくすためではなく、経験の異なる参加者が同じ目標に到達できるようにするためだ。ただし、現場に合わせるという説明だけでは、どこまで変更してよいかが曖昧になる。守るべき目的と、変えてよい方法を分けて示す必要があるだろう。原則と実情を対立させるのではなく、変更した方法が原則をどう支えるのかを説明できてこそ、調整の妥当性を検討できる。","audioText":"ある団体は、全国で同じ研修を実施していたが、現場の状況に即して内容を調整することにした。共通の基準をなくすためではなく、経験の異なる参加者が同じ目標に到達できるようにするためだ。ただし、現場に合わせるという説明だけでは、どこまで変更してよいかが曖昧になる。守るべき目的と、変えてよい方法を分けて示す必要があるだろう。原則と実情を対立させるのではなく、変更した方法が原則をどう支えるのかを説明できてこそ、調整の妥当性を検討できる。","note":"“同じ目標に到達できるよう” — The methods can change in support of the invariant objective.","source":"course.html#lesson-537"},"lesson:542:meaning":{"title":"Explain a correction without dismissing someone","front":"What alternative leaves room for the listener to ask for help?","answer":"Offer to explain from that point if needed.","context":"","promptAudio":"「説明するまでもありませんが」と言われたとき、聞き手は質問しにくくなることがある。話し手にとっては確認のつもりでも、知っていて当然だという含みが相手をためらわせるからだ。もちろん、すでに共有されている内容を毎回長く説明する必要はない。大切なのは、理解を前提に省略する前に、確認や質問の機会を残すことである。「必要でしたら、ここからご説明します」と言い換えるだけでも、相手が選びやすくなる。簡潔さと配慮は、どちらか一方を犠牲にしなければ実現できないものではない。","model":"「説明するまでもありませんが」と言われたとき、聞き手は質問しにくくなることがある。話し手にとっては確認のつもりでも、知っていて当然だという含みが相手をためらわせるからだ。もちろん、すでに共有されている内容を毎回長く説明する必要はない。大切なのは、理解を前提に省略する前に、確認や質問の機会を残すことである。「必要でしたら、ここからご説明します」と言い換えるだけでも、相手が選びやすくなる。簡潔さと配慮は、どちらか一方を犠牲にしなければ実現できないものではない。","audioText":"「説明するまでもありませんが」と言われたとき、聞き手は質問しにくくなることがある。話し手にとっては確認のつもりでも、知っていて当然だという含みが相手をためらわせるからだ。もちろん、すでに共有されている内容を毎回長く説明する必要はない。大切なのは、理解を前提に省略する前に、確認や質問の機会を残すことである。「必要でしたら、ここからご説明します」と言い換えるだけでも、相手が選びやすくなる。簡潔さと配慮は、どちらか一方を犠牲にしなければ実現できないものではない。","note":"“必要でしたら、ここからご説明します” — A conditional offer preserves both brevity and a real choice to request explanation.","source":"course.html#lesson-542"},"lesson:547:meaning":{"title":"Synthesize competing accounts","front":"What alternative explanation does Report B offer for the higher attendance count?","answer":"Existing visitors may be returning more often.","context":"","promptAudio":"次の二つは授業用の架空の報告である。報告Ａは「夜間の開館後、来館者が増えた。利用機会の拡大という目的に照らして、変更は評価できる」と述べる。報告Ｂは「総数は増えたが、来館できる人の範囲が広がったかは分からない。以前からの利用者が訪れる回数を増やした可能性もある」と指摘する。両者は来館者の増加という観察では一致しているが、評価に必要な情報の十分性について立場が違う。統合した議論を書くなら、片方を誤りと決めつける前に、目的の定義と指標の関係を整理し、追加で何を確かめればよいかを示す必要がある。","model":"次の二つは授業用の架空の報告である。報告Ａは「夜間の開館後、来館者が増えた。利用機会の拡大という目的に照らして、変更は評価できる」と述べる。報告Ｂは「総数は増えたが、来館できる人の範囲が広がったかは分からない。以前からの利用者が訪れる回数を増やした可能性もある」と指摘する。両者は来館者の増加という観察では一致しているが、評価に必要な情報の十分性について立場が違う。統合した議論を書くなら、片方を誤りと決めつける前に、目的の定義と指標の関係を整理し、追加で何を確かめればよいかを示す必要がある。","audioText":"次の二つは授業用の架空の報告である。報告Ａは「夜間の開館後、来館者が増えた。利用機会の拡大という目的に照らして、変更は評価できる」と述べる。報告Ｂは「総数は増えたが、来館できる人の範囲が広がったかは分からない。以前からの利用者が訪れる回数を増やした可能性もある」と指摘する。両者は来館者の増加という観察では一致しているが、評価に必要な情報の十分性について立場が違う。統合した議論を書くなら、片方を誤りと決めつける前に、目的の定義と指標の関係を整理し、追加で何を確かめればよいかを示す必要がある。","note":"“以前からの利用者が訪れる回数を増やした” — More visits need not imply a broader group of people gaining access.","source":"course.html#lesson-547"}};
